import { Service, inject, Injectable } from '@angular/core';
import { CookieService } from './cookie';
import { environment } from '../../../environments/environment';

export interface ActiveLocation {
  id: string;
  name: string;
  city: string | null;
  state: string | null;
  country: string | null;
  lat: number;
  lng: number;
}

@Injectable()
export abstract class ExplorationStorage {
  abstract get(): ActiveLocation | null;
  abstract set(context: ActiveLocation): void;
  abstract clear(): void;
}

@Service()
export class CookieExplorationStorage extends ExplorationStorage {
  private readonly COOKIE_KEY = 'orita.exploration';
  #cookieService = inject(CookieService);

  get(): ActiveLocation | null {
    const raw = this.#cookieService.get(this.COOKIE_KEY);
    if (!raw) return null;
    try {
      return JSON.parse(raw) as ActiveLocation;
    } catch (e) {
      return null;
    }
  }

  set(context: ActiveLocation): void {
    // 1 year expiry
    const expires = new Date();
    expires.setFullYear(expires.getFullYear() + 1);

    this.#cookieService.set(this.COOKIE_KEY, JSON.stringify(context), {
      expires,
      path: '/',
      sameSite: 'Lax',
      secure: environment.production
    });
  }

  clear(): void {
    this.#cookieService.delete(this.COOKIE_KEY, { path: '/', sameSite: 'Lax' });
  }
}

export type ConversationType = 'DIRECT' | 'GROUP';
export type ConversationStatus = 'ACTIVE' | 'CLOSED';
export type MediaType = 'IMAGE' | 'VIDEO';
export type MessageSyncState = 'LOCAL' | 'QUEUED' | 'UPLOADING' | 'UPLOADED' | 'SENDING' | 'FAILED_UPLOAD' | 'FAILED_SEND' | 'SYNCED';

export interface IMessageReadReceipt {
  messageId: string;
  participantId: string;
  readAt: string;
}

export interface IMessageEmbed {
  id: string;
  embedType: string;
  targetId: string;
  title: string;
  subtitle?: string | null;
  imageUrl?: string | null;
  ctaLabel?: string | null;
  ctaPath?: string | null;
}

export interface IMessageAttachment {
  id: string;
  url: string; // Server URL for synced attachments
  mediaType: 'IMAGE' | 'VIDEO' | 'AUDIO' | 'FILE';
  mimeType: string;
  size?: number;
}

export interface MessageAttachmentView {
  id: string; // The UI view ID (can map to attachment id)
  attachment?: IMessageAttachment; // If synced
  remoteUrl?: string; // If synced
  localBlobId?: string; // If local
  isLocal: boolean;
  kind: 'IMAGE' | 'VIDEO' | 'AUDIO' | 'FILE';
}

export interface IMessage {
  id: string;
  conversationId: string;
  participantId: string;
  senderDisplayName: string;
  senderAvatarUrl?: string | null;
  content?: string | null;
  mediaUrl?: string | null;
  mediaType?: MediaType | null;
  attachments?: IMessageAttachment[];
  embeds: IMessageEmbed[];
  createdAt: string;
  readReceipts: IMessageReadReceipt[];

  // UI state for optimistic updates
  syncState?: MessageSyncState;
  attachmentViews?: MessageAttachmentView[];
}

export interface IConversationAnchor {
  id: string;
  title: string;
  subtitle?: string | null;
  imageUrl?: string | null;
  businessId?: string | null;
  listingId?: string | null;
  tourId?: string | null;
  locationId?: string | null;
}

export type IMessagePreviewDescriptor =
  | { kind: 'TEXT'; text: string }
  | { kind: 'EMBED'; embedType: string }
  | { kind: 'ATTACHMENT'; attachmentType: string }
  | { kind: 'SYSTEM'; text: string };

export interface IMessagePreview {
  id: string;
  content?: string | null;
  participantId: string;
  senderDisplayName: string;
  createdAt: string;
  descriptor: IMessagePreviewDescriptor;
}

export interface IConversationPreview {
  id: string;
  type: ConversationType;
  title: string;
  avatarUrl?: string | null;
  anchor?: IConversationAnchor | null;
  latestMessage?: IMessagePreview;
  unreadCount: number;
  lastActivityAt: string;
}

export type ConversationLoadStatus = 'idle' | 'loading' | 'loaded' | 'error';

export interface IConversation {
  id: string;
  type: ConversationType;
  status: ConversationStatus;
  title?: string | null;
  avatarUrl?: string | null;
  anchorId?: string | null;
  anchor?: IConversationAnchor | null;
  participantIds: string[];
  createdAt: string;
  updatedAt: string;
  messages?: IMessage[];
  viewer?: { participantId: string };

  // Computed UI state
  unreadCount?: number;
  lastActivityAt?: string;
  latestMessage?: IMessagePreview;
}

export interface CreateConversationDto {
  type: ConversationType;
  invitedParticipantIds: string[];
  anchor?: { type: string; targetId: string };
  initialMessage?: string;
}

export interface SendMessageDto {
  content?: string;
  mediaUrl?: string; // Legacy/backward compatibility
  mediaType?: MediaType; // Legacy/backward compatibility
  attachmentIds?: string[]; // Referencing uploaded media resources
  embeds?: { embedType: string; targetId: string }[];
}

export type AttachmentSource = 'CAMERA' | 'GALLERY' | 'FILES' | 'AUDIO';

export interface AttachmentSelection {
  source: AttachmentSource;
  files: File[];
}

export interface SendMessageCommand {
  content?: string;
  embeds?: { embedType: string; targetId: string }[];
  attachments?: AttachmentSelection[];
}

export interface WsMessageNewEvent {
  conversationId: string;
  message: IMessage;
}

export interface WsReadReceiptEvent {
  conversationId: string;
  messageId: string;
  participantId: string;
  readAt: string;
}

export interface PendingAttachment {
  id: string;
  blob: Blob;
  filename: string;
  mimeType: string;
  size: number;
  kind: 'IMAGE' | 'VIDEO' | 'AUDIO' | 'FILE';
}

export interface QueuedAttachment {
  attachmentId: string;
  uploadState: 'PENDING' | 'UPLOADING' | 'COMPLETED' | 'FAILED';
  uploadProgress: number; // 0-100
  uploadedMediaId?: string;
}

export interface QueuedMessage {
  id: string;
  conversationId: string;
  payload: SendMessageDto;
  attemptCount: number;
  lastError: string | null;
  lastAttemptAt: number | null;
  createdAt: number;
  status: MessageSyncState;
  attachments?: QueuedAttachment[];
}

import { Component, computed, inject, signal, effect, OnInit } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Router } from '@angular/router';
import { httpResource } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { parsePhoneNumberWithError, CountryCode, getCountryCallingCode } from 'libphonenumber-js';
import { form, FormField, required, minLength, maxLength } from '@angular/forms/signals';
import {
  LucideLoaderCircle,
  LucideGlobe,
  LucideMapPin,
  LucideLayoutGrid,
  LucideIconInput,
} from '@lucide/angular';
import { ToastService } from '../../../../core/services/toast';
import { IBusinessProfile, BusinessType } from '../business.interface';
import { environment } from '../../../../../environments/environment';
import { AppFormField } from '../../../../shared/form-field/form-field';
import { MediaSelector } from '../../../../shared/media-selector/media-selector';
import { ICategory } from '../../../home/home.interface';
import { CategoryPicker } from '../../../../shared/category-picker/category-picker';
import { LocationPicker } from '../../../../shared/location-picker/location-picker';
import { Location } from '../../../../core/services/location.service';
import { MediaService } from '../../../../core/services/media.service';

interface BusinessTypeOption {
  value: BusinessType;
  label: string;
  description: string;
  icon: LucideIconInput;
}

export interface IEditBusinessForm {
  name: string;
  businessType: BusinessType;
  description: string;
  websiteUrl: string;
  contactPhone: string;
  whatsapp: string;
  contactEmail: string;
  location: string;
  latitude: number | null;
  longitude: number | null;
  primaryCategoryId: string;
  secondaryCategoryIds: string[];
}

@Component({
  selector: 'app-edit-business',
  imports: [FormField, AppFormField, MediaSelector, LocationPicker, LucideLoaderCircle, CategoryPicker],
  templateUrl: './edit-business.html',
  styleUrl: './edit-business.css',
})
export class EditBusiness implements OnInit {
  #http = inject(HttpClient);
  #router = inject(Router);
  #toast = inject(ToastService);

  readonly business = httpResource<IBusinessProfile>(
    () => `${environment.apiUrl}/users/me/business`
  );

  readonly loading = signal(false);
  readonly avatarFile = signal<File | null>(null);
  readonly coverFile = signal<File | null>(null);
  #mediaService = inject(MediaService);
  readonly selectedCountryCode = signal<CountryCode | undefined>(undefined);

  readonly categories = signal<ICategory[]>([]);

  ngOnInit() {
  }

  readonly availableSecondaryCategories = computed(() => {
    const primaryId = this.model().primaryCategoryId;
    return this.categories().filter((c) => c.id !== primaryId);
  });

  toggleSecondaryCategory(categoryId: string): void {
    this.model.update((m) => {
      const current = m.secondaryCategoryIds ?? [];
      if (current.includes(categoryId)) {
        return { ...m, secondaryCategoryIds: current.filter((id) => id !== categoryId) };
      } else if (current.length < 5) {
        return { ...m, secondaryCategoryIds: [...current, categoryId] };
      } else {
        this.#toast.error('Limit Reached', 'You can only select up to 5 secondary categories.');
        return m;
      }
    });
  }

  isSecondaryCategorySelected(categoryId: string): boolean {
    return (this.model().secondaryCategoryIds ?? []).includes(categoryId);
  }

  onLocationPicked(loc: Location): void {
    if (loc.countryCode) {
      this.selectedCountryCode.set(loc.countryCode.toUpperCase() as CountryCode);
    }
    this.model.update((m) => ({
      ...m,
      location: loc.name || loc.formattedAddress || 'Unknown',
      latitude: loc.latitude,
      longitude: loc.longitude,
    }));
  }

  onCategoryPicked(id: string): void {
    this.model.update((m) => ({ ...m, primaryCategoryId: id }));
  }

  readonly model = signal<IEditBusinessForm>({
    name: '',
    businessType: 'ONLINE',
    description: '',
    websiteUrl: '',
    contactPhone: '',
    whatsapp: '',
    contactEmail: '',
    location: '',
    latitude: null,
    longitude: null,
    primaryCategoryId: '',
    secondaryCategoryIds: [],
  });

  readonly businessForm = form(this.model, (f) => {
    required(f.name, { message: 'Business name is required' });
    minLength(f.name, 2, { message: 'Name must be at least 2 characters' });
    maxLength(f.name, 100, { message: 'Name must be under 100 characters' });
    maxLength(f.description, 1000, { message: 'Description must be under 1000 characters' });
    maxLength(f.websiteUrl, 200, { message: 'Website URL must be under 200 characters' });
    maxLength(f.contactPhone, 20, { message: 'Phone number must be under 20 characters' });
    maxLength(f.whatsapp, 20, { message: 'WhatsApp number must be under 20 characters' });
    maxLength(f.contactEmail, 100, { message: 'Email must be under 100 characters' });
    maxLength(f.location, 200, { message: 'Location must be under 200 characters' });
  });

  readonly isFormInvalid = computed(() => this.businessForm().invalid());

  readonly phonePlaceholder = computed(() => {
    const cc = this.selectedCountryCode();
    if (cc) {
      try {
        return `e.g. +${getCountryCallingCode(cc)}...`;
      } catch { }
    }
    return 'e.g. +1234567890';
  });

  readonly phoneWarning = computed(() => {
    const phone = this.model().contactPhone;
    const locCountry = this.selectedCountryCode();
    if (phone && locCountry) {
      try {
        const parsed = parsePhoneNumberWithError(phone, locCountry);
        if (parsed.isValid() && parsed.country && parsed.country !== locCountry) {
          return `This business is located in ${locCountry} but uses a ${parsed.country} phone number.`;
        }
      } catch { }
    }
    return null;
  });

  readonly whatsappWarning = computed(() => {
    const phone = this.model().whatsapp;
    const locCountry = this.selectedCountryCode();
    if (phone && locCountry) {
      try {
        const parsed = parsePhoneNumberWithError(phone, locCountry);
        if (parsed.isValid() && parsed.country && parsed.country !== locCountry) {
          return `This business is located in ${locCountry} but uses a ${parsed.country} WhatsApp number.`;
        }
      } catch { }
    }
    return null;
  });

  readonly typeOptions: BusinessTypeOption[] = [
    {
      value: 'ONLINE',
      label: 'Online',
      description: 'Operates entirely online',
      icon: LucideGlobe,
    },
    {
      value: 'PHYSICAL',
      label: 'Physical',
      description: 'Has a physical location',
      icon: LucideMapPin,
    },
    {
      value: 'HYBRID',
      label: 'Hybrid',
      description: 'Online and in-person',
      icon: LucideLayoutGrid,
    },
  ];

  constructor() {
    effect(() => {
      const biz = this.business.value();
      if (biz) {
        this.model.set({
          name: biz.name,
          businessType: biz.businessType,
          description: biz.description ?? '',
          websiteUrl: biz.websiteUrl ?? '',
          contactPhone: biz.contactPhone ?? '',
          whatsapp: biz.whatsapp ?? '',
          contactEmail: biz.contactEmail ?? '',
          location: biz.location ?? '',
          latitude: biz.latitude ?? null,
          longitude: biz.longitude ?? null,
          primaryCategoryId: biz.primaryCategoryId ?? '',
          secondaryCategoryIds: biz.secondaryCategoryIds ?? [],
        });
      }
    });
  }

  selectType(type: BusinessType): void {
    this.model.update((m) => ({ ...m, businessType: type }));
  }

  onAvatarChanged(files: File[]): void {
    this.avatarFile.set(files[0] || null);
  }

  onAvatarRemoved(): void {
    this.avatarFile.set(null);
  }

  onCoverChanged(files: File[]): void {
    this.coverFile.set(files[0] || null);
  }

  onCoverRemoved(): void {
    this.coverFile.set(null);
  }

  async onSubmit(event: Event): Promise<void> {
    event.preventDefault();
    if (this.businessForm().invalid()) {
      this.businessForm().markAsTouched();
      return;
    }
    const biz = this.business.value();
    if (!biz) return;

    this.loading.set(true);
    try {
      const payload = {
        name: this.model().name,
        businessType: this.model().businessType,
        ...(this.model().description && { description: this.model().description }),
        ...(this.model().websiteUrl && { websiteUrl: this.model().websiteUrl }),
        ...(this.model().contactPhone && { contactPhone: this.model().contactPhone }),
        ...(this.model().whatsapp && { whatsapp: this.model().whatsapp }),
        ...(this.model().contactEmail && { contactEmail: this.model().contactEmail }),
        ...(this.model().location && { location: this.model().location }),
        ...(this.model().latitude !== null && { latitude: this.model().latitude }),
        ...(this.model().longitude !== null && { longitude: this.model().longitude }),
        primaryCategoryId: this.model().primaryCategoryId,
        ...(this.model().secondaryCategoryIds.length > 0 && { secondaryCategoryIds: this.model().secondaryCategoryIds }),
      };

      try {
        if (payload.contactPhone) {
          const parsed = parsePhoneNumberWithError(payload.contactPhone, this.selectedCountryCode());
          if (!parsed.isValid()) {
             this.#toast.error('Invalid phone', 'Please enter a valid phone number.');
             this.loading.set(false);
             return;
          }
          payload.contactPhone = parsed.format('E.164');
        }
        if (payload.whatsapp) {
          const parsed = parsePhoneNumberWithError(payload.whatsapp, this.selectedCountryCode());
          if (!parsed.isValid()) {
             this.#toast.error('Invalid WhatsApp', 'Please enter a valid WhatsApp number.');
             this.loading.set(false);
             return;
          }
          payload.whatsapp = parsed.format('E.164');
        }
      } catch {
        this.#toast.error('Invalid phone', 'Please enter a valid phone/WhatsApp number.');
        this.loading.set(false);
        return;
      }

      await firstValueFrom(
        this.#http.patch(`${environment.apiUrl}/business/${biz.id}`, payload)
      );

      const avatar = this.avatarFile();
      if (avatar) {
        await new Promise<void>((resolve, reject) => {
          this.#mediaService.uploadMedia('business-profile', biz.id, 'LOGO', avatar).subscribe({
            next: (state) => {
              if (state.state === 'complete') resolve();
            },
            error: (err) => reject(err),
          });
        });
      }

      const cover = this.coverFile();
      if (cover) {
        await new Promise<void>((resolve, reject) => {
          this.#mediaService.uploadMedia('business-profile', biz.id, 'BANNER', cover).subscribe({
            next: (state) => {
              if (state.state === 'complete') resolve();
            },
            error: (err) => reject(err),
          });
        });
      }

      this.#toast.success('Profile updated', 'Your business profile has been updated.');
      this.#router.navigate(['/profile/business']);
    } catch (err) {
      const message =
        err instanceof HttpErrorResponse
          ? (err.error?.message ?? 'Could not update profile. Please try again.')
          : 'An unexpected error occurred.';
      this.#toast.error('Error', message);
    } finally {
      this.loading.set(false);
    }
  }
}

import { Injectable, inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

export enum CacheKeys {
  PROFILE = 'PROFILE_v1',
  DRAFTS = 'DRAFTS_v1',
  CONVERSATIONS = 'CONVERSATIONS_v1',
}

export interface CacheEntry<T> {
  value: T;
  updatedAt: number;
  version: string;
}

export interface StorageAdapter {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
  clear(): void;
}

export class LocalStorageAdapter implements StorageAdapter {
  private readonly storage: Storage | null = null;

  constructor(platformId: Object) {
    if (isPlatformBrowser(platformId)) {
      this.storage = window.localStorage;
    }
  }

  getItem(key: string): string | null {
    if (!this.storage) return null;
    try {
      return this.storage.getItem(key);
    } catch {
      return null;
    }
  }

  setItem(key: string, value: string): void {
    if (!this.storage) return;
    try {
      this.storage.setItem(key, value);
    } catch (err) {
      console.warn('LocalStorage limit exceeded or disabled', err);
    }
  }

  removeItem(key: string): void {
    if (!this.storage) return;
    try {
      this.storage.removeItem(key);
    } catch {}
  }

  clear(): void {
    if (!this.storage) return;
    try {
      this.storage.clear();
    } catch {}
  }
}

@Injectable({ providedIn: 'root' })
export class CacheService {
  private readonly SCHEMA_VERSION = 'v1';
  private readonly SCHEMA_KEY = 'ORITA_CACHE_SCHEMA_VERSION';

  private adapter: StorageAdapter;
  private platformId = inject(PLATFORM_ID);

  constructor() {
    this.adapter = new LocalStorageAdapter(this.platformId);
    if (isPlatformBrowser(this.platformId)) {
      this.verifySchemaVersion();
    }
  }

  private verifySchemaVersion(): void {
    const currentVersion = this.adapter.getItem(this.SCHEMA_KEY);
    if (currentVersion !== this.SCHEMA_VERSION) {
      console.log(`Cache schema version mismatch (Expected ${this.SCHEMA_VERSION}, got ${currentVersion}). Clearing cache.`);
      this.adapter.clear();
      this.adapter.setItem(this.SCHEMA_KEY, this.SCHEMA_VERSION);
    }
  }

  get<T>(key: CacheKeys): T | null {
    const raw = this.adapter.getItem(key);
    if (!raw) return null;

    try {
      const entry = JSON.parse(raw) as CacheEntry<T>;
      // If version in key changed, it wouldn't match the key, but we can also verify schema
      return entry.value;
    } catch {
      return null;
    }
  }

  set<T>(key: CacheKeys, value: T): void {
    const entry: CacheEntry<T> = {
      value,
      updatedAt: Date.now(),
      version: this.SCHEMA_VERSION,
    };
    this.adapter.setItem(key, JSON.stringify(entry));
  }

  remove(key: CacheKeys): void {
    this.adapter.removeItem(key);
  }
}

