import { Service, computed, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { httpResource } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../environments/environment';
import { ICategory } from '../../pages/home/home.interface';

export interface ICategoryAttribute {
  id: string;
  key: string;
  label: string;
  type: 'STRING' | 'NUMBER' | 'BOOLEAN' | 'SELECT';
  isRequired: boolean;
  options: string[] | null;
}

@Service()
export class CategoryService {
  #http = inject(HttpClient);

  readonly categories = httpResource<ICategory[]>(() => `${environment.apiUrl}/categories`);

  readonly leafCategories = computed<ICategory[]>(() => {
    const cats = this.categories.value() ?? [];
    return cats.flatMap((root) => (root.children ?? []).filter((c) => c.isActive));
  });

  async getCategoryAttributes(categoryId: string): Promise<ICategoryAttribute[]> {
    const cats = this.categories.value() ?? [];
    let slug = '';

    for (const root of cats) {
      if (root.id === categoryId) slug = root.slug;
      for (const child of root.children || []) {
        if (child.id === categoryId) slug = child.slug;
      }
    }

    if (!slug) return [];

    try {
      return await firstValueFrom(
        this.#http.get<ICategoryAttribute[]>(`${environment.apiUrl}/categories/${slug}/attributes`)
      );
    } catch {
      return [];
    }
  }
}

import { Component, inject, signal, computed, effect } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { httpResource } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { form, FormField, required } from '@angular/forms/signals';
import {
  LucideKey,
  LucideTrash2,
  LucideLink,
  LucideUnlink,
  LucideEye,
  LucideEyeOff,
} from '@lucide/angular';
import { RouterLink } from '@angular/router';
import { ToastService } from '../../../core/services/toast';
import { environment } from '../../../../environments/environment';
import { IProfile } from '../profile.interface';
import { Drawer } from '../../../shared/drawer/drawer';
import { AppFormField } from '../../../shared/form-field/form-field';
import { AppGoogleSignIn } from '../../../shared/google-sign-in/google-sign-in';
import { ValidationService } from '../../../core/services/validation.service';

interface IChangePassword {
  currentPassword: string;
  newPassword: string;
}

interface IAddPassword {
  password: string;
}

@Component({
  selector: 'app-security',
  imports: [
    FormField,
    RouterLink,
    LucideKey,
    LucideTrash2,
    LucideLink,
    LucideUnlink,
    LucideEye,
    LucideEyeOff,
    Drawer,
    AppFormField,
    AppGoogleSignIn,
  ],
  templateUrl: './security.html',
  styleUrl: './security.css',
})
export class Security {
  #http = inject(HttpClient);
  #toast = inject(ToastService);
  #validation = inject(ValidationService);

  readonly profile = httpResource<IProfile>(() => `${environment.apiUrl}/users/me`);
  readonly loading = signal(false);

  readonly hasPassword = computed(() => this.profile.value()?.hasPassword ?? false);

  // Drawers
  readonly isPasswordDrawerOpen = signal(false);
  readonly isGoogleDrawerOpen = signal(false);

  // Password visibility toggles
  readonly showCurrentPassword = signal(false);
  readonly showNewPassword = signal(false);
  readonly showAddPassword = signal(false);

  // Models for Signal Forms
  readonly changePasswordModel = signal<IChangePassword>({
    currentPassword: '',
    newPassword: '',
  });

  readonly addPasswordModel = signal<IAddPassword>({
    password: '',
  });

  // Signal Forms
  readonly changePasswordForm = form(this.changePasswordModel, (f) => {
    required(f.currentPassword, { message: 'Current password is required' });
    this.#validation.validatePassword(f.newPassword);
  });

  readonly addPasswordForm = form(this.addPasswordModel, (f) => {
    this.#validation.validatePassword(f.password);
  });

  constructor() {
    effect(() => {
      const isOpen = this.isPasswordDrawerOpen();
      if (!isOpen) {
        // Reset models
        this.changePasswordModel.set({ currentPassword: '', newPassword: '' });
        this.addPasswordModel.set({ password: '' });

        // Reset form signals state
        this.changePasswordForm().reset();
        this.addPasswordForm().reset();

        // Reset visibility toggles
        this.showCurrentPassword.set(false);
        this.showNewPassword.set(false);
        this.showAddPassword.set(false);
      }
    });
  }

  async onGoogleIdTokenReceived(idToken: string): Promise<void> {
    try {
      this.loading.set(true);
      await firstValueFrom(this.#http.post(`${environment.apiUrl}/auth/google/link`, { idToken }));
      this.#toast.success('Linked', 'Google account has been linked.');
      this.profile.reload();
      this.isGoogleDrawerOpen.set(false);
    } catch (err) {
      const message =
        err instanceof HttpErrorResponse
          ? (err.error?.message ?? 'Failed to link Google.')
          : err instanceof Error
            ? err.message
            : 'Failed to link Google.';
      this.#toast.error('Error', message);
    } finally {
      this.loading.set(false);
    }
  }

  async onUnlinkGoogle(): Promise<void> {
    try {
      this.loading.set(true);
      await firstValueFrom(this.#http.delete(`${environment.apiUrl}/auth/google/unlink`));
      this.#toast.success('Unlinked', 'Google account has been unlinked.');
      this.isGoogleDrawerOpen.set(false);
      this.profile.reload();
    } catch (err) {
      this.#toast.error('Error', 'Failed to unlink Google.');
    } finally {
      this.loading.set(false);
    }
  }

  async onSubmitPassword(event: Event): Promise<void> {
    event.preventDefault();

    if (this.hasPassword()) {
      if (this.changePasswordForm().invalid()) {
        this.changePasswordForm().markAsTouched();
        return;
      }
      this.loading.set(true);
      try {
        await firstValueFrom(
          this.#http.post(
            `${environment.apiUrl}/auth/password/change`,
            this.changePasswordModel(),
          ),
        );
        this.#toast.success('Success', 'Password has been changed.');
        this.isPasswordDrawerOpen.set(false);
      } catch (err) {
        const message =
          err instanceof HttpErrorResponse
            ? (err.error?.message ?? 'Could not change password.')
            : 'Could not change password.';
        this.#toast.error('Error', message);
      } finally {
        this.loading.set(false);
      }
    } else {
      if (this.addPasswordForm().invalid()) {
        this.addPasswordForm().markAsTouched();
        return;
      }
      this.loading.set(true);
      try {
        await firstValueFrom(
          this.#http.post(
            `${environment.apiUrl}/auth/password/add`,
            this.addPasswordModel(),
          ),
        );
        this.#toast.success('Success', 'Password has been added.');
        this.isPasswordDrawerOpen.set(false);
        this.profile.reload(); // needed so hasPassword() flips to true afterward
      } catch (err) {
        const message =
          err instanceof HttpErrorResponse
            ? (err.error?.message ?? 'Could not add password.')
            : 'Could not add password.';
        this.#toast.error('Error', message);
      } finally {
        this.loading.set(false);
      }
    }
  }

  onDeleteAccount(): void {
    this.#toast.info('Not available', 'Account deletion is currently disabled.');
  }
}

import { Service, inject } from '@angular/core';
import { HttpClient, HttpEvent, HttpEventType, HttpRequest } from '@angular/common/http';
import { Observable, concat, of } from 'rxjs';
import { map, switchMap } from 'rxjs/operators';
import { environment } from '../../../environments/environment';

export type MediaResourceType =
  | 'business-profile'
  | 'listing'
  | 'review'
  | 'business-tour'
  | 'user-profile'
  | 'message';

const ROUTE_MAP: Record<MediaResourceType, string> = {
  'business-profile': 'business-profiles',
  listing: 'listings',
  review: 'reviews',
  'business-tour': 'business-tours',
  'user-profile': 'users',
  'message': 'conversations',
};

export interface IMediaResponse {
  id: string;
  url: string;
  mediaType: 'IMAGE' | 'VIDEO';
  role: string;
  order: number | null;
  createdAt: string;
}

export interface IUploadIntentRequest {
  role: string;
}

export interface IUploadIntentResponse {
  signature: string;
  timestamp: number;
  apiKey?: string;
  cloudName?: string;
  intentId: string;
  folder: string;
  publicId: string;
}

export interface IConsumeIntentRequest {
  intentId: string;
  publicId: string;
  version: string;
}

export interface IDirectUploadResult {
  publicId: string;
  version: string;
}

export type UploadState =
  | { state: 'intent' }
  | { state: 'uploading'; progress: number }
  | { state: 'persisting' }
  | { state: 'complete'; media: IMediaResponse };

@Service()
export class MediaService {
  #http = inject(HttpClient);
  #apiUrl = environment.apiUrl;

  generateIntent(
    resourceType: MediaResourceType,
    resourceId: string,
    role: string
  ): Observable<IUploadIntentResponse> {
    const route = ROUTE_MAP[resourceType];
    const path = resourceType === 'user-profile' ? `${route}/me` : `${route}/${resourceId}`;
    return this.#http.post<IUploadIntentResponse>(
      `${this.#apiUrl}/${path}/media/upload-intent`,
      { role }
    );
  }

  performDirectUpload(
    intent: IUploadIntentResponse,
    file: File
  ): Observable<{ type: 'progress'; value: number } | { type: 'result'; value: IDirectUploadResult }> {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('timestamp', intent.timestamp.toString());
    formData.append('signature', intent.signature);
    formData.append('folder', intent.folder);
    formData.append('public_id', intent.publicId);
    if (intent.apiKey) {
      formData.append('api_key', intent.apiKey);
    }

    // Default to a fallback if cloudName isn't provided, though backend should provide it for Cloudinary
    const cloudName = intent.cloudName || 'dlyxyhofo';
    const uploadUrl = `${environment.cloudinaryUploadBaseUrl}/${cloudName}/auto/upload`;

    const req = new HttpRequest('POST', uploadUrl, formData, {
      reportProgress: true,
    });

    return this.#http.request<any>(req).pipe(
      map((event: HttpEvent<any>) => {
        if (event.type === HttpEventType.UploadProgress) {
          const progress = event.total ? Math.round((100 * event.loaded) / event.total) : 0;
          return { type: 'progress', value: progress };
        } else if (event.type === HttpEventType.Response) {
          return {
            type: 'result',
            value: {
              publicId: event.body.public_id,
              version: event.body.version.toString(),
            },
          };
        }
        return { type: 'progress', value: 0 };
      })
    );
  }

  consumeIntent(
    resourceType: MediaResourceType,
    resourceId: string,
    payload: IConsumeIntentRequest
  ): Observable<IMediaResponse> {
    const route = ROUTE_MAP[resourceType];
    const path = resourceType === 'user-profile' ? `${route}/me` : `${route}/${resourceId}`;
    return this.#http.post<IMediaResponse>(
      `${this.#apiUrl}/${path}/media`,
      payload
    );
  }

  uploadMedia(
    resourceType: MediaResourceType,
    resourceId: string,
    role: string,
    file: File
  ): Observable<UploadState> {
    return new Observable<UploadState>((observer) => {
      observer.next({ state: 'intent' });

      const subscription = this.generateIntent(resourceType, resourceId, role).pipe(
        switchMap((intent) => {
          return this.performDirectUpload(intent, file).pipe(
            switchMap((uploadEvent) => {
              if (uploadEvent.type === 'progress') {
                return of<UploadState>({ state: 'uploading', progress: uploadEvent.value });
              } else if (uploadEvent.type === 'result') {
                return concat(
                  of<UploadState>({ state: 'persisting' }),
                  this.consumeIntent(resourceType, resourceId, {
                    intentId: intent.intentId,
                    publicId: uploadEvent.value.publicId,
                    version: uploadEvent.value.version,
                  }).pipe(
                    map((media) => ({ state: 'complete', media } as UploadState))
                  )
                );
              }
              // Ignore other HttpEvent types safely
              return of<UploadState>({ state: 'uploading', progress: 0 });
            })
          );
        })
      ).subscribe({
        next: (state) => {
          // Prevent duplicates or noise (like 0% immediately after 0%)
          observer.next(state);
        },
        error: (err) => observer.error(err),
        complete: () => observer.complete(),
      });

      return () => {
        subscription.unsubscribe();
      };
    });
  }

  deleteMedia(mediaId: string): Observable<void> {
    return this.#http.delete<void>(`${this.#apiUrl}/media/${mediaId}`);
  }
}

