import { Component, computed, inject, signal, OnInit } from '@angular/core';
import { ActivatedRoute, RouterLink, Router } from '@angular/router';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import {
  LucideSave,
} from '@lucide/angular';
import { MediaSelector } from '../../../../../shared/media-selector/media-selector';
import { environment } from '../../../../../../environments/environment';
import { ToastService } from '../../../../../core/services/toast';
import { MediaService } from '../../../../../core/services/media.service';
import { IListing, ICategory } from '../listing.interface';
import { form, FormField, required } from '@angular/forms/signals';
import { AppFormField } from '../../../../../shared/form-field/form-field';
import { CategoryService, ICategoryAttribute } from '../../../../../core/services/category.service';

interface IMedia {
  id: string;
  url: string;
  role: 'COVER' | 'GALLERY';
}

@Component({
  selector: 'app-edit-listing',
  imports: [FormField, AppFormField, LucideSave, MediaSelector],
  templateUrl: './edit-listing.html',
  styleUrl: './edit-listing.css',
})
export class EditListing implements OnInit {
  #http = inject(HttpClient);
  #toast = inject(ToastService);
  #route = inject(ActivatedRoute);
  #router = inject(Router);
  #categoryService = inject(CategoryService);
  #mediaService = inject(MediaService);

  readonly listingId = signal<string>('');
  readonly listing = signal<IListing | null>(null);
  readonly categories = signal<ICategory[]>([]);
  readonly attributes = signal<ICategoryAttribute[]>([]);

  // Media State
  readonly coverMedia = signal<IMedia | null>(null);
  readonly galleryMedia = signal<IMedia[]>([]);

  readonly initialCoverUrl = computed(() => this.coverMedia()?.url ?? []);
  readonly initialGalleryUrls = computed(() => this.galleryMedia().map(m => m.url));

  // Media Tracking State (Deferred Uploads)
  readonly coverFileToAdd = signal<File | null>(null);
  readonly galleryFilesToAdd = signal<File[]>([]);
  readonly mediaIdsToDelete = signal<string[]>([]);

  // Form State
  readonly editModel = signal({
    title: '',
    description: '',
    categoryId: '',
    minPrice: null as number | null,
    maxPrice: null as number | null,
    isNegotiable: false,
    attributesData: {} as Record<string, any>,
  });

  readonly editForm = form(this.editModel, (f) => {
    required(f.title, { message: 'Title is required' });
  });

  readonly isLoading = signal(true);
  readonly isSaving = signal(false);

  ngOnInit() {
    this.listingId.set(this.#route.snapshot.paramMap.get('listingId') ?? '');
    this.loadData();
  }

  async loadData() {
    this.isLoading.set(true);
    try {
      const cats = await firstValueFrom(
        this.#http.get<ICategory[]>(`${environment.apiUrl}/categories`),
      );
      this.categories.set(cats);

      const l = await firstValueFrom(
        this.#http.get<IListing>(`${environment.apiUrl}/listings/mine/${this.listingId()}`),
      );
      this.listing.set(l);

      const attrsData = l.attributes || {};

      this.editModel.set({
        title: l.title,
        description: l.description || '',
        categoryId: l.categoryId || '',
        minPrice: l.minPrice ? Number(l.minPrice) : null,
        maxPrice: l.maxPrice ? Number(l.maxPrice) : null,
        isNegotiable: l.isNegotiable,
        attributesData: attrsData
      });

      const mediaRes = await firstValueFrom(
        this.#http.get<{ cover?: IMedia; gallery: IMedia[] }>(
          `${environment.apiUrl}/listings/${this.listingId()}/media`,
        ),
      );
      this.coverMedia.set(mediaRes.cover || null);
      this.galleryMedia.set(mediaRes.gallery || []);

      if (l.categoryId) {
        await this.loadCategoryAttributes(l.categoryId);
      }
    } catch (err) {
      this.#toast.error('Error', 'Could not load listing details.');
      this.#router.navigate(['../'], { relativeTo: this.#route });
    } finally {
      this.isLoading.set(false);
    }
  }

  async loadCategoryAttributes(catId: string) {
    if (catId) {
      const attrs = await this.#categoryService.getCategoryAttributes(catId);
      this.attributes.set(attrs);

      this.editModel.update(m => {
        const currentAttrs = { ...m.attributesData };
        attrs.forEach(attr => {
          if (currentAttrs[attr.key] === undefined) {
            currentAttrs[attr.key] = '';
          }
        });
        return { ...m, attributesData: currentAttrs };
      });
    } else {
      this.attributes.set([]);
    }
  }

  async onCategoryChange(catId: string) {
    this.editModel.update(m => ({ ...m, categoryId: catId, attributesData: {} }));
    await this.loadCategoryAttributes(catId);
  }

  updateAttribute(key: string, value: any) {
    this.editModel.update(m => ({
      ...m,
      attributesData: {
        ...m.attributesData,
        [key]: value
      }
    }));
  }

  async saveChanges() {
    if (this.editForm().invalid()) {
      this.editForm().markAsTouched();
      return;
    }
    this.isSaving.set(true);
    try {
      // 1. Save listing details
      const val = this.editModel();
      const payload = {
        title: val.title,
        description: val.description,
        categoryId: val.categoryId,
        price: {
          minPrice: val.minPrice,
          maxPrice: val.maxPrice,
          isNegotiable: val.isNegotiable,
          currencyCode: 'NGN',
        },
        attributes: val.attributesData,
      };

      await firstValueFrom(
        this.#http.patch(`${environment.apiUrl}/listings/${this.listingId()}`, payload),
      );

      // 2. Process Deletions
      const toDelete = this.mediaIdsToDelete();
      if (toDelete.length > 0) {
        for (const id of toDelete) {
          await firstValueFrom(
            this.#http.delete(`${environment.apiUrl}/listings/${this.listingId()}/media/${id}`)
          ).catch(() => {});
        }
      }

      // 3. Process Uploads
      const cover = this.coverFileToAdd();
      if (cover) {
        await this.uploadMedia(cover, 'COVER');
      }

      const gallery = this.galleryFilesToAdd();
      if (gallery.length > 0) {
        for (const file of gallery) {
          await this.uploadMedia(file, 'GALLERY');
        }
      }

      // 4. Reload Data to sync state
      await this.loadData();
      this.coverFileToAdd.set(null);
      this.galleryFilesToAdd.set([]);
      this.mediaIdsToDelete.set([]);

      this.#toast.success('Saved', 'Listing updated successfully.');
    } catch (err) {
      this.#toast.error('Error', 'Could not update listing.');
    } finally {
      this.isSaving.set(false);
    }
  }

  onCoverChanged(files: File[]) {
    this.coverFileToAdd.set(files[0] ?? null);
  }

  onCoverRemoved(url: string) {
    const media = this.coverMedia();
    if (media && media.url === url) {
      this.mediaIdsToDelete.update(ids => [...ids, media.id]);
      this.coverMedia.set(null);
    }
  }

  onGalleryChanged(files: File[]) {
    this.galleryFilesToAdd.set(files);
  }

  onGalleryRemoved(url: string) {
    const media = this.galleryMedia().find(m => m.url === url);
    if (media) {
      this.mediaIdsToDelete.update(ids => [...ids, media.id]);
      this.galleryMedia.update(g => g.filter(m => m.id !== media.id));
    }
  }



  private async uploadMedia(file: File, role: 'COVER' | 'GALLERY') {
    try {
      await new Promise<void>((resolve, reject) => {
        this.#mediaService.uploadMedia('listing', this.listingId(), role, file).subscribe({
          next: (state) => {
            if (state.state === 'complete') {
              resolve();
            }
          },
          error: (err) => reject(err),
        });
      });
    } catch (err) {
      console.error('Failed to upload media', err);
      throw err;
    }
  }

  async deleteMedia(mediaId: string, role: 'COVER' | 'GALLERY') {
    if (!confirm('Are you sure you want to delete this image?')) return;

    try {
      await firstValueFrom(this.#http.delete(`${environment.apiUrl}/media/${mediaId}`));
      if (role === 'COVER') {
        this.coverMedia.set(null);
      } else {
        this.galleryMedia.update((g) => g.filter((m) => m.id !== mediaId));
      }
      this.#toast.success('Done', 'Image deleted.');
    } catch (err) {
      this.#toast.error('Error', 'Could not delete image.');
    }
  }

  get leafCategories() {
    const cats = this.categories() ?? [];
    return cats.flatMap((root) => root.children.filter((child) => child.isActive));
  }
}

import {
  Component,
  computed,
  inject,
  input,
  output,
  signal,
  DestroyRef,
} from '@angular/core';
import { LucideUpload, LucideX } from '@lucide/angular';

export interface IMediaPreview {
  url: string;
  isNew: boolean;
  file?: File;
}

@Component({
  selector: 'app-media-selector',
  imports: [LucideUpload, LucideX],
  templateUrl: './media-selector.html',
  styleUrl: './media-selector.css',
})
export class MediaSelector {
  #destroyRef = inject(DestroyRef);

  multiple = input<boolean>(false);
  accept = input<string>('image/*');
  maxSizeMb = input<number>(5);
  initialUrls = input<string[] | string>([]);

  readonly filesChanged = output<File[]>();
  readonly mediaRemoved = output<string>();

  readonly isDragging = signal(false);
  readonly selectedFiles = signal<{ file: File; objectUrl: string }[]>([]);

  readonly previews = computed<IMediaPreview[]>(() => {
    const list: IMediaPreview[] = [];

    // Parse initial URLs input (can be string or string[])
    const initials = this.initialUrls();
    if (initials) {
      const urlsArray = Array.isArray(initials) ? initials : [initials];
      urlsArray.forEach((url) => {
        if (url) {
          list.push({ url, isNew: false });
        }
      });
    }

    // Append newly selected files
    this.selectedFiles().forEach((s) => {
      list.push({ url: s.objectUrl, isNew: true, file: s.file });
    });

    return list;
  });

  constructor() {
    this.#destroyRef.onDestroy(() => {
      this.selectedFiles().forEach((s) => URL.revokeObjectURL(s.objectUrl));
    });
  }

  onDragOver(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    this.isDragging.set(true);
  }

  onDragLeave(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    this.isDragging.set(false);
  }

  onDrop(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    this.isDragging.set(false);

    const files = event.dataTransfer?.files;
    if (files && files.length > 0) {
      this.handleFiles(Array.from(files));
    }
  }

  onFileSelected(event: Event): void {
    const inputEl = event.target as HTMLInputElement;
    if (inputEl.files && inputEl.files.length > 0) {
      this.handleFiles(Array.from(inputEl.files));
    }
  }

  private handleFiles(files: File[]): void {
    // Validate types & sizes
    const validFiles = files.filter((file) => {
      const isTypeValid = file.type.match(this.accept().replace('*', '.*'));
      const isSizeValid = file.size / (1024 * 1024) <= this.maxSizeMb();
      return isTypeValid && isSizeValid;
    });

    if (validFiles.length === 0) return;

    const newSelections = validFiles.map((file) => ({
      file,
      objectUrl: URL.createObjectURL(file),
    }));

    if (this.multiple()) {
      this.selectedFiles.update((existing) => [...existing, ...newSelections]);
    } else {
      // Clear old object URL if replacing single file
      this.selectedFiles().forEach((s) => URL.revokeObjectURL(s.objectUrl));
      this.selectedFiles.set([newSelections[0]]);
    }

    this.filesChanged.emit(this.selectedFiles().map((s) => s.file));
  }

  removePreview(preview: IMediaPreview): void {
    if (preview.isNew && preview.file) {
      URL.revokeObjectURL(preview.url);

      // Remove from selected files
      this.selectedFiles.update((files) => files.filter((f) => f.file !== preview.file));
      this.filesChanged.emit(this.selectedFiles().map((s) => s.file));
    } else {
      // Remove from initial URLs
      this.mediaRemoved.emit(preview.url);
    }
  }
}

import { Service, inject } from '@angular/core';
import { HttpClient, HttpEvent, HttpEventType, HttpRequest } from '@angular/common/http';
import { Observable, concat, of } from 'rxjs';
import { map, switchMap } from 'rxjs/operators';
import { environment } from '../../../environments/environment';

export type MediaResourceType =
  | 'business-profile'
  | 'listing'
  | 'review'
  | 'business-tour'
  | 'user-profile'
  | 'message';

const ROUTE_MAP: Record<MediaResourceType, string> = {
  'business-profile': 'business-profiles',
  listing: 'listings',
  review: 'reviews',
  'business-tour': 'business-tours',
  'user-profile': 'users',
  'message': 'conversations',
};

export interface IMediaResponse {
  id: string;
  url: string;
  mediaType: 'IMAGE' | 'VIDEO';
  role: string;
  order: number | null;
  createdAt: string;
}

export interface IUploadIntentRequest {
  role: string;
}

export interface IUploadIntentResponse {
  signature: string;
  timestamp: number;
  apiKey?: string;
  cloudName?: string;
  intentId: string;
  folder: string;
  publicId: string;
}

export interface IConsumeIntentRequest {
  intentId: string;
  publicId: string;
  version: string;
}

export interface IDirectUploadResult {
  publicId: string;
  version: string;
}

export type UploadState =
  | { state: 'intent' }
  | { state: 'uploading'; progress: number }
  | { state: 'persisting' }
  | { state: 'complete'; media: IMediaResponse };

@Service()
export class MediaService {
  #http = inject(HttpClient);
  #apiUrl = environment.apiUrl;

  generateIntent(
    resourceType: MediaResourceType,
    resourceId: string,
    role: string
  ): Observable<IUploadIntentResponse> {
    const route = ROUTE_MAP[resourceType];
    const path = resourceType === 'user-profile' ? `${route}/me` : `${route}/${resourceId}`;
    return this.#http.post<IUploadIntentResponse>(
      `${this.#apiUrl}/${path}/media/upload-intent`,
      { role }
    );
  }

  performDirectUpload(
    intent: IUploadIntentResponse,
    file: File
  ): Observable<{ type: 'progress'; value: number } | { type: 'result'; value: IDirectUploadResult }> {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('timestamp', intent.timestamp.toString());
    formData.append('signature', intent.signature);
    formData.append('folder', intent.folder);
    formData.append('public_id', intent.publicId);
    if (intent.apiKey) {
      formData.append('api_key', intent.apiKey);
    }

    // Default to a fallback if cloudName isn't provided, though backend should provide it for Cloudinary
    const cloudName = intent.cloudName || 'dlyxyhofo';
    const uploadUrl = `${environment.cloudinaryUploadBaseUrl}/${cloudName}/auto/upload`;

    const req = new HttpRequest('POST', uploadUrl, formData, {
      reportProgress: true,
    });

    return this.#http.request<any>(req).pipe(
      map((event: HttpEvent<any>) => {
        if (event.type === HttpEventType.UploadProgress) {
          const progress = event.total ? Math.round((100 * event.loaded) / event.total) : 0;
          return { type: 'progress', value: progress };
        } else if (event.type === HttpEventType.Response) {
          return {
            type: 'result',
            value: {
              publicId: event.body.public_id,
              version: event.body.version.toString(),
            },
          };
        }
        return { type: 'progress', value: 0 };
      })
    );
  }

  consumeIntent(
    resourceType: MediaResourceType,
    resourceId: string,
    payload: IConsumeIntentRequest
  ): Observable<IMediaResponse> {
    const route = ROUTE_MAP[resourceType];
    const path = resourceType === 'user-profile' ? `${route}/me` : `${route}/${resourceId}`;
    return this.#http.post<IMediaResponse>(
      `${this.#apiUrl}/${path}/media`,
      payload
    );
  }

  uploadMedia(
    resourceType: MediaResourceType,
    resourceId: string,
    role: string,
    file: File
  ): Observable<UploadState> {
    return new Observable<UploadState>((observer) => {
      observer.next({ state: 'intent' });

      const subscription = this.generateIntent(resourceType, resourceId, role).pipe(
        switchMap((intent) => {
          return this.performDirectUpload(intent, file).pipe(
            switchMap((uploadEvent) => {
              if (uploadEvent.type === 'progress') {
                return of<UploadState>({ state: 'uploading', progress: uploadEvent.value });
              } else if (uploadEvent.type === 'result') {
                return concat(
                  of<UploadState>({ state: 'persisting' }),
                  this.consumeIntent(resourceType, resourceId, {
                    intentId: intent.intentId,
                    publicId: uploadEvent.value.publicId,
                    version: uploadEvent.value.version,
                  }).pipe(
                    map((media) => ({ state: 'complete', media } as UploadState))
                  )
                );
              }
              // Ignore other HttpEvent types safely
              return of<UploadState>({ state: 'uploading', progress: 0 });
            })
          );
        })
      ).subscribe({
        next: (state) => {
          // Prevent duplicates or noise (like 0% immediately after 0%)
          observer.next(state);
        },
        error: (err) => observer.error(err),
        complete: () => observer.complete(),
      });

      return () => {
        subscription.unsubscribe();
      };
    });
  }

  deleteMedia(mediaId: string): Observable<void> {
    return this.#http.delete<void>(`${this.#apiUrl}/media/${mediaId}`);
  }
}

