export type ConversationType = 'DIRECT' | 'GROUP';
export type ConversationStatus = 'ACTIVE' | 'CLOSED';
export type MediaType = 'IMAGE' | 'VIDEO';
export type MessageSyncState = 'LOCAL' | 'QUEUED' | 'UPLOADING' | 'UPLOADED' | 'SENDING' | 'FAILED_UPLOAD' | 'FAILED_SEND' | 'SYNCED';

export interface IMessageReadReceipt {
  messageId: string;
  participantId: string;
  readAt: string;
}

export interface IMessageEmbed {
  id: string;
  embedType: string;
  targetId: string;
  title: string;
  subtitle?: string | null;
  imageUrl?: string | null;
  ctaLabel?: string | null;
  ctaPath?: string | null;
}

export interface IMessageAttachment {
  id: string;
  url: string; // Server URL for synced attachments
  mediaType: 'IMAGE' | 'VIDEO' | 'AUDIO' | 'FILE';
  mimeType: string;
  size?: number;
}

export interface MessageAttachmentView {
  id: string; // The UI view ID (can map to attachment id)
  attachment?: IMessageAttachment; // If synced
  remoteUrl?: string; // If synced
  localBlobId?: string; // If local
  isLocal: boolean;
  kind: 'IMAGE' | 'VIDEO' | 'AUDIO' | 'FILE';
}

export interface IMessage {
  id: string;
  conversationId: string;
  participantId: string;
  senderDisplayName: string;
  senderAvatarUrl?: string | null;
  content?: string | null;
  mediaUrl?: string | null;
  mediaType?: MediaType | null;
  attachments?: IMessageAttachment[];
  embeds: IMessageEmbed[];
  createdAt: string;
  readReceipts: IMessageReadReceipt[];

  // UI state for optimistic updates
  syncState?: MessageSyncState;
  attachmentViews?: MessageAttachmentView[];
}

export interface IConversationAnchor {
  id: string;
  title: string;
  subtitle?: string | null;
  imageUrl?: string | null;
  businessId?: string | null;
  listingId?: string | null;
  tourId?: string | null;
  locationId?: string | null;
}

export type IMessagePreviewDescriptor =
  | { kind: 'TEXT'; text: string }
  | { kind: 'EMBED'; embedType: string }
  | { kind: 'ATTACHMENT'; attachmentType: string }
  | { kind: 'SYSTEM'; text: string };

export interface IMessagePreview {
  id: string;
  content?: string | null;
  participantId: string;
  senderDisplayName: string;
  createdAt: string;
  descriptor: IMessagePreviewDescriptor;
}

export interface IConversationPreview {
  id: string;
  type: ConversationType;
  title: string;
  avatarUrl?: string | null;
  anchor?: IConversationAnchor | null;
  latestMessage?: IMessagePreview;
  unreadCount: number;
  lastActivityAt: string;
}

export type ConversationLoadStatus = 'idle' | 'loading' | 'loaded' | 'error';

export interface IConversation {
  id: string;
  type: ConversationType;
  status: ConversationStatus;
  title?: string | null;
  avatarUrl?: string | null;
  anchorId?: string | null;
  anchor?: IConversationAnchor | null;
  participantIds: string[];
  createdAt: string;
  updatedAt: string;
  messages?: IMessage[];
  viewer?: { participantId: string };

  // Computed UI state
  unreadCount?: number;
  lastActivityAt?: string;
  latestMessage?: IMessagePreview;
}

export interface CreateConversationDto {
  type: ConversationType;
  invitedParticipantIds: string[];
  anchor?: { type: string; targetId: string };
  initialMessage?: string;
}

export interface SendMessageDto {
  content?: string;
  mediaUrl?: string; // Legacy/backward compatibility
  mediaType?: MediaType; // Legacy/backward compatibility
  attachmentIds?: string[]; // Referencing uploaded media resources
  embeds?: { embedType: string; targetId: string }[];
}

export type AttachmentSource = 'CAMERA' | 'GALLERY' | 'FILES' | 'AUDIO';

export interface AttachmentSelection {
  source: AttachmentSource;
  files: File[];
}

export interface SendMessageCommand {
  content?: string;
  embeds?: { embedType: string; targetId: string }[];
  attachments?: AttachmentSelection[];
}

export interface WsMessageNewEvent {
  conversationId: string;
  message: IMessage;
}

export interface WsReadReceiptEvent {
  conversationId: string;
  messageId: string;
  participantId: string;
  readAt: string;
}

export interface PendingAttachment {
  id: string;
  blob: Blob;
  filename: string;
  mimeType: string;
  size: number;
  kind: 'IMAGE' | 'VIDEO' | 'AUDIO' | 'FILE';
}

export interface QueuedAttachment {
  attachmentId: string;
  uploadState: 'PENDING' | 'UPLOADING' | 'COMPLETED' | 'FAILED';
  uploadProgress: number; // 0-100
  uploadedMediaId?: string;
}

export interface QueuedMessage {
  id: string;
  conversationId: string;
  payload: SendMessageDto;
  attemptCount: number;
  lastError: string | null;
  lastAttemptAt: number | null;
  createdAt: number;
  status: MessageSyncState;
  attachments?: QueuedAttachment[];
}

import { Component, computed, inject, signal } from '@angular/core';
import { httpResource } from '@angular/common/http';
import { Router } from '@angular/router';
import {
  LucideUser,
  LucideBuilding2,
  LucideBookmark,
  LucideShieldCheck,
  LucidePaintbrush,
  LucideChevronRight,
  LucideLogOut,
  LucideTriangleAlert,
  LucideDynamicIcon,
  LucideList,
  LucideIconInput,
} from '@lucide/angular';
import { IProfile } from './profile.interface';
import { AuthService } from '../../core/services/auth.service';
import { environment } from '../../../environments/environment';
import { CreateBusiness } from './business/create/create-business';
import { SeoComponent } from '../../shared/seo/seo.component';
import { AppHeader } from '../../shared/app-header/app-header';
import { Avatar } from '../../shared/ui/avatar/avatar';

interface NavItem {
  icon: LucideIconInput;
  label: string;
  description: string;
  route?: string;
  action?: string;
}

interface NavGroup {
  title: string;
  items: NavItem[];
}

const ALWAYS_VISIBLE_SETTINGS: NavItem[] = [
  {
    icon: LucideList,
    label: 'Discovery Preferences',
    description: 'Personalize your feed and interests',
    route: '/profile/preferences',
  },
  {
    icon: LucideShieldCheck,
    label: 'Privacy & Security',
    description: 'Manage auth methods and account security',
    route: '/profile/security',
  },
  {
    icon: LucidePaintbrush,
    label: 'Appearance',
    description: 'Customise how Orita looks for you',
    route: '/profile/appearance',
  },
];

const SAVED_ITEM: NavItem = {
  icon: LucideBookmark,
  label: 'Library',
  description: 'Your saved listings and businesses',
  route: '/profile/saved',
};

const MY_BUSINESS: NavItem = {
  icon: LucideBuilding2,
  label: 'My Business',
  description: 'Manage your business profile',
  route: '/profile/business',
};

const START_BUSINESS: NavItem = {
  icon: LucideBuilding2,
  label: 'Start a Business',
  description: 'Create a profile and reach customers on Orita',
  action: 'create-business',
};

@Component({
  selector: 'app-profile',
  imports: [
    LucideDynamicIcon,
    LucideChevronRight,
    LucideLogOut,
    LucideTriangleAlert,
    CreateBusiness,
    SeoComponent,
    AppHeader,
    Avatar,
  ],
  templateUrl: './profile.html',
  styleUrl: './profile.css',
})
export class Profile {
  #auth = inject(AuthService);
  #router = inject(Router);

  readonly profile = httpResource<IProfile>(() => `${environment.apiUrl}/users/me`);
  readonly isCreateBusinessOpen = signal(false);

  readonly navGroups = computed<NavGroup[]>(() => {
    const businessItem = this.profile.value()?.businessId ? MY_BUSINESS : START_BUSINESS;
    return [
      {
        title: 'Workspace',
        items: [businessItem, SAVED_ITEM],
      },
      {
        title: 'Account Settings',
        items: ALWAYS_VISIBLE_SETTINGS,
      },
    ];
  });

  readonly seoConfig = computed(() => {
    const p = this.profile.value();
    return {
      title: p ? `${p.username}'s Profile` : 'Profile',
      description: 'Manage your Orita account, business, and saved items.',
    };
  });

  navigate(item: NavItem): void {
    if (item.action === 'create-business') {
      this.isCreateBusinessOpen.set(true);
      return;
    }
    if (item.route) {
      this.#router.navigate([item.route]);
    }
  }

  onBusinessCreated(): void {
    this.profile.reload();
    this.#router.navigate(['/profile/business']);
  }

  logout(): void {
    this.#auth.logout();
  }

  formatDate(iso: string): string {
    return new Intl.DateTimeFormat('en', { month: 'long', year: 'numeric' }).format(new Date(iso));
  }
}

