import { Service, inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { ToastService } from './toast';

import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../environments/environment';

export interface ShareData {
  title?: string;
  text?: string;
  url?: string;
}

export interface SuggestedShareRecipientDto {
  userId: string;
  username: string;
  displayName?: string;
  avatarUrl?: string;
}

export interface RecentShareableDto {
  type: 'BUSINESS' | 'LISTING' | 'TOUR';
  targetId: string;
  title: string;
  imageUrl?: string;
  lastInteractedAt: string;
}

export interface ShareableSearchResult {
  type: 'BUSINESS' | 'LISTING' | 'TOUR';
  targetId: string;
  title: string;
  subtitle?: string;
  imageUrl?: string;
}

export interface InternalShareDto {
  embedType: 'BUSINESS' | 'LISTING' | 'TOUR' | 'LOCATION';
  targetId: string;
  recipientIds: string[];
  content?: string;
}

export interface ShareResultDto {
  recipientId: string;
  conversationId: string;
  messageId: string;
}

@Service()
export class ShareService {
  #platformId = inject(PLATFORM_ID);
  #toast = inject(ToastService);
  #http = inject(HttpClient);

  readonly isSupported = isPlatformBrowser(this.#platformId) && !!navigator.share;

  async share(data: ShareData): Promise<void> {
    if (!isPlatformBrowser(this.#platformId)) return;

    if (this.isSupported) {
      try {
        await navigator.share(data);
      } catch (err) {
        // AbortError is perfectly normal (user canceled share sheet). We only care about other errors.
        if (err instanceof DOMException && err.name === 'AbortError') return;
        this.#fallback(data);
      }
    } else {
      this.#fallback(data);
    }
  }

  async #fallback(data: ShareData): Promise<void> {
    const textToCopy = data.url || data.text || '';
    if (!textToCopy) return;

    try {
      await navigator.clipboard.writeText(textToCopy);
      this.#toast.success('Link copied', 'The link has been copied to your clipboard.');
    } catch (err) {
      this.#toast.error('Copy failed', 'Unable to copy to clipboard.');
    }
  }

  async getSuggestedRecipients(): Promise<SuggestedShareRecipientDto[]> {
    return firstValueFrom(this.#http.get<SuggestedShareRecipientDto[]>(`${environment.apiUrl}/sharing/suggested-recipients`));
  }

  async getRecentShares(): Promise<RecentShareableDto[]> {
    return firstValueFrom(this.#http.get<RecentShareableDto[]>(`${environment.apiUrl}/sharing/recent`));
  }

  async searchShareables(query: string): Promise<ShareableSearchResult[]> {
    return firstValueFrom(this.#http.get<ShareableSearchResult[]>(`${environment.apiUrl}/search/shareables`, { params: { q: query } }));
  }

  async shareInternal(dto: InternalShareDto): Promise<ShareResultDto[]> {
    return firstValueFrom(this.#http.post<ShareResultDto[]>(`${environment.apiUrl}/share/internal`, dto));
  }
}

import { Component, computed, input, output } from '@angular/core';
import { IBusinessProfile } from '../../pages/profile/business/business.interface';
import { LucideCircle } from '@lucide/angular';
import { RouterLink } from '@angular/router';

interface ScoreItem {
  id: string;
  label: string;
  isComplete: boolean;
  points: number;
  actionUrl?: string | null;
  actionId?: string | null;
}

@Component({
  selector: 'app-visibility-score',
  imports: [LucideCircle, RouterLink],
  templateUrl: './visibility-score.html',
  styleUrl: './visibility-score.css',
})
export class VisibilityScore {
  readonly business = input.required<IBusinessProfile>();
  readonly listingCount = input.required<number>();
  readonly actionTriggered = output<string>();

  readonly scoreItems = computed<ScoreItem[]>(() => {
    const biz = this.business();
    return [
      { id: 'cover', label: 'Add cover photo', isComplete: !!biz.coverUrl, points: 20, actionUrl: '/profile/business/edit' },
      { id: 'listing', label: 'Create first listing', isComplete: this.listingCount() > 0, points: 20, actionId: 'create-listing' },
      { id: 'logo', label: 'Upload logo', isComplete: !!biz.avatarUrl, points: 10, actionUrl: '/profile/business/edit' },
      { id: 'phone', label: 'Add phone number', isComplete: !!biz.contactPhone, points: 10, actionUrl: '/profile/business/edit' },
      { id: 'desc', label: 'Add description', isComplete: !!biz.description, points: 10, actionUrl: '/profile/business/edit' },
      { id: 'location', label: 'Add location', isComplete: !!biz.latitude, points: 10, actionUrl: '/profile/business/edit' },
      { id: 'name', label: 'Business name', isComplete: !!biz.name, points: 10 },
      { id: 'category', label: 'Category', isComplete: !!biz.primaryCategoryId, points: 10 },
    ];
  });

  readonly totalScore = computed(() => {
    return this.scoreItems().reduce((acc, item) => item.isComplete ? acc + item.points : acc, 0);
  });

  readonly incompleteItems = computed(() => {
    // Only show incomplete items that have an action, prioritizing cover and listing
    return this.scoreItems().filter(item => !item.isComplete && (item.actionUrl || item.actionId));
  });

  triggerAction(item: ScoreItem) {
    if (item.actionId) {
      this.actionTriggered.emit(item.actionId);
    }
  }
}

