import { Injectable, OnDestroy, inject } from '@angular/core';
import { DatabaseService } from './database.service';

@Injectable({ providedIn: 'root' })
export class AttachmentPreviewService implements OnDestroy {
  #db = inject(DatabaseService);
  private objectUrls = new Map<string, string>(); // blobId -> objectUrl

  /**
   * Creates an object URL for a File or Blob synchronously.
   */
  createPreview(blobId: string, blob: Blob | File): string {
    if (this.objectUrls.has(blobId)) {
      return this.objectUrls.get(blobId)!;
    }
    const url = URL.createObjectURL(blob);
    this.objectUrls.set(blobId, url);
    return url;
  }

  /**
   * Resolves a preview URL asynchronously, reading from IDB if necessary.
   */
  async resolvePreviewUrl(localBlobId?: string, remoteUrl?: string): Promise<string | null> {
    if (localBlobId) {
      if (this.objectUrls.has(localBlobId)) {
        return this.objectUrls.get(localBlobId)!;
      }
      const pendingAtt = await this.#db.getAttachment(localBlobId);
      if (pendingAtt && pendingAtt.blob) {
        return this.createPreview(localBlobId, pendingAtt.blob);
      }
    }
    return remoteUrl || null;
  }

  getPreview(blobId: string): string | undefined {
    return this.objectUrls.get(blobId);
  }

  revokePreview(blobId: string): void {
    const url = this.objectUrls.get(blobId);
    if (url) {
      URL.revokeObjectURL(url);
      this.objectUrls.delete(blobId);
    }
  }

  revokeAllPreviews(): void {
    for (const url of this.objectUrls.values()) {
      URL.revokeObjectURL(url);
    }
    this.objectUrls.clear();
  }

  ngOnDestroy(): void {
    this.revokeAllPreviews();
  }
}

import { Injectable } from '@angular/core';

export interface ValidationResult {
  valid: boolean;
  error?: string;
}

@Injectable({ providedIn: 'root' })
export class AttachmentValidatorService {
  private readonly MAX_ATTACHMENTS = 10;
  private readonly MAX_FILE_SIZE_BYTES = 50 * 1024 * 1024; // 50MB
  private readonly SUPPORTED_MIME_TYPES = new Set([
    'image/jpeg',
    'image/png',
    'image/webp',
    'image/gif',
    'video/mp4',
    'video/webm',
    'audio/mpeg',
    'audio/ogg',
    'audio/wav',
    'application/pdf',
  ]);

  validateAttachments(currentCount: number, newFiles: File[]): ValidationResult {
    if (currentCount + newFiles.length > this.MAX_ATTACHMENTS) {
      return { valid: false, error: `You can only attach up to ${this.MAX_ATTACHMENTS} files.` };
    }

    for (const file of newFiles) {
      if (file.size > this.MAX_FILE_SIZE_BYTES) {
        return { valid: false, error: `File ${file.name} exceeds the 50MB size limit.` };
      }

      // Basic MIME type check. Some OSs might return empty string for unknown types.
      // We do a loose check if it starts with image/, video/, audio/ or is exactly supported.
      if (!this.SUPPORTED_MIME_TYPES.has(file.type)) {
        if (!file.type.startsWith('image/') && !file.type.startsWith('video/') && !file.type.startsWith('audio/')) {
           return { valid: false, error: `File type ${file.type || 'unknown'} is not supported for ${file.name}.` };
        }
      }
    }

    return { valid: true };
  }
}

import { Service, inject, signal } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { ToastService } from '../services/toast';
import { CookieService } from '../services/cookie';
import { ILogin, ILoginResponse } from '../../pages/auth/login/login.interface';
import { IRegister } from '../../pages/auth/register/register.interface';
import { environment } from '../../../environments/environment';
import { ExplorationService } from './exploration.service';
import { IProfile } from '../../pages/profile/profile.interface';
import { effect } from '@angular/core';
import { NotificationPermissionService } from './notification-permission.service';
import { CacheService, CacheKeys } from './cache.service';

const TOKEN_KEY = 'auth_token';

@Service()
export class AuthService {
  #http = inject(HttpClient);
  #router = inject(Router);
  #toast = inject(ToastService);
  #cookie = inject(CookieService);
  #exploration = inject(ExplorationService);
  #push = inject(NotificationPermissionService);
  #cache = inject(CacheService);

  readonly token = signal<string | undefined>(this.#cookie.get(TOKEN_KEY));
  readonly currentUser = signal<IProfile | null>(this.#cache.get<IProfile>(CacheKeys.PROFILE));

  constructor() {
    effect(() => {
      const t = this.token();
      if (t) {
        this.fetchCurrentUser();
      } else {
        this.currentUser.set(null);
      }
    });
  }

  async fetchCurrentUser(): Promise<void> {
    try {
      const profile = await firstValueFrom(
        this.#http.get<IProfile>(`${environment.apiUrl}/users/me`)
      );
      this.#cache.set(CacheKeys.PROFILE, profile);
      this.currentUser.set(profile);
    } catch (err) {
      console.error('Failed to fetch user profile', err);
    }
  }

  async login(credentials: ILogin & { remember: boolean }, returnUrl: string = '/home'): Promise<boolean> {
    try {
      const { remember, ...payload } = credentials;
      const res = await firstValueFrom(
        this.#http.post<ILoginResponse>(`${environment.apiUrl}/auth/login`, payload),
      );
      this.#setToken(res.token, remember ? new Date(res.expiresAt) : undefined);
      this.#toast.success('Logged in', 'Welcome back!');
      await this.#router.navigateByUrl(returnUrl);
      return true;
    } catch (err) {
      const message =
        err instanceof HttpErrorResponse
          ? (err.error?.message ?? 'Login failed. Please try again.')
          : 'An unexpected error occurred.';
      this.#toast.error('Error', message);
      return false;
    }
  }

  async loginWithGoogle(idToken: string, returnUrl: string = '/home'): Promise<boolean> {
    try {
      const res = await firstValueFrom(
        this.#http.post<ILoginResponse>(`${environment.apiUrl}/auth/google`, { idToken }),
      );

      if (res.token) {
        this.#setToken(res.token, res.expiresAt ? new Date(res.expiresAt) : undefined);
      }

      if (returnUrl === '/home' && !this.#exploration.hasLocation()) {
        returnUrl = '/welcome';
      }
      this.#toast.success('Logged in', 'Welcome to Orita!');
      await this.#router.navigateByUrl(returnUrl);
      return true;
    } catch (err) {
      const message =
        err instanceof HttpErrorResponse
          ? (err.error?.message ?? 'Google Sign-In failed. Please try again.')
          : 'An unexpected error occurred.';
      this.#toast.error('Error', message);
      return false;
    }
  }

  async register(credentials: IRegister): Promise<void> {
    try {
      await firstValueFrom(this.#http.post(`${environment.apiUrl}/accounts/register`, credentials));
      // Seamlessly authenticate after registration
      const loginSuccess = await this.login({
        email: credentials.email,
        password: credentials.password,
        remember: false,
      }, '/welcome');
      if (loginSuccess) {
        this.#toast.success('Account created', 'Welcome to Orita!');
      }
    } catch (err) {
      const message =
        err instanceof HttpErrorResponse
          ? (err.error?.message ?? 'Registration failed. Please try again.')
          : 'An unexpected error occurred.';
      this.#toast.error('Error', message);
    }
  }

  logout(expired = false, returnUrl?: string): void {
    // Unsubscribe from push notifications before removing the token
    this.#push.unsubscribe().catch((err) => console.error(err));

    this.#cookie.delete(TOKEN_KEY);
    this.#cache.remove(CacheKeys.PROFILE);
    this.token.set(undefined);
    this.currentUser.set(null);
    if (expired) {
      this.#toast.error('Session Expired', 'Please log in again to continue.');
    } else {
      this.#toast.info('Goodbye', 'You have been logged out.');
    }
    this.#router.navigate(['/auth/login'], returnUrl ? { queryParams: { returnUrl } } : undefined);
  }

  #setToken(token: string, expires?: Date): void {
    this.#cookie.set(TOKEN_KEY, token, {
      expires,
      secure: environment.production,
    });
    this.token.set(token);
  }
}

