export interface ActiveLocation {
  id: string;
  name: string;
  city: string | null;
  state: string | null;
  country: string | null;
  lat: number;
  lng: number;
}

@Injectable()
export abstract class ExplorationStorage {
  abstract get(): ActiveLocation | null;
  abstract set(context: ActiveLocation): void;
  abstract clear(): void;
}

@Service()
export class CookieExplorationStorage extends ExplorationStorage {
  private readonly COOKIE_KEY = 'orita.exploration';
  #cookieService = inject(CookieService);

  get(): ActiveLocation | null {
    const raw = this.#cookieService.get(this.COOKIE_KEY);
    if (!raw) return null;
    try {
      return JSON.parse(raw) as ActiveLocation;
    } catch (e) {
      return null;
    }
  }

  set(context: ActiveLocation): void {
    // 1 year expiry
    const expires = new Date();
    expires.setFullYear(expires.getFullYear() + 1);

    this.#cookieService.set(this.COOKIE_KEY, JSON.stringify(context), {
      expires,
      path: '/',
      sameSite: 'Lax',
      secure: environment.production
    });
  }

  clear(): void {
    this.#cookieService.delete(this.COOKIE_KEY, { path: '/', sameSite: 'Lax' });
  }
}

import { Service, inject, PLATFORM_ID, REQUEST } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

export interface CookieOptions {
  expires?: Date;
  path?: string;
  secure?: boolean;
  sameSite?: 'Strict' | 'Lax' | 'None';
}

@Service()
export class CookieService {
  #platformId = inject(PLATFORM_ID);
  #request = inject(REQUEST, { optional: true }) as any;

  get(name: string): string | undefined {
    let cookieStr = '';
    if (isPlatformBrowser(this.#platformId)) {
      cookieStr = document.cookie;
    } else if (this.#request) {
      if (typeof this.#request.headers?.get === 'function') {
        cookieStr = this.#request.headers.get('cookie') || '';
      } else {
        cookieStr = this.#request.headers?.cookie || '';
      }
    }

    if (!cookieStr) return undefined;

    const match = cookieStr.match(new RegExp(`(?:^|; )${name}=([^;]*)`));
    return match ? decodeURIComponent(match[1]) : undefined;
  }

  set(name: string, value: string, options: CookieOptions = {}): void {
    if (!isPlatformBrowser(this.#platformId)) return;
    const { expires, path = '/', secure = false, sameSite = 'Strict' } = options;
    let cookie = `${name}=${encodeURIComponent(value)}; path=${path}; SameSite=${sameSite}`;
    if (secure) cookie += '; Secure';
    if (expires) cookie += `; expires=${expires.toUTCString()}`;
    document.cookie = cookie;
  }

  delete(name: string, options: Pick<CookieOptions, 'path' | 'sameSite'> = {}): void {
    if (!isPlatformBrowser(this.#platformId)) return;
    const { path = '/', sameSite = 'Strict' } = options;
    document.cookie = `${name}=; path=${path}; expires=${new Date(0).toUTCString()}; SameSite=${sameSite}`;
  }

  has(name: string): boolean {
    return this.get(name) !== undefined;
  }
}

import { Injectable, PLATFORM_ID, inject } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { openDB, IDBPDatabase, DBSchema } from 'idb';
import { IConversationPreview, IMessage, SendMessageDto, QueuedMessage, PendingAttachment } from './messaging.types';

export interface OritaDB extends DBSchema {
  outgoing_messages: {
    key: string;
    value: QueuedMessage;
    indexes: {
      'by-conversation': string;
      'by-status': string;
      'by-created': number;
    };
  };
  conversations: {
    key: string;
    value: IConversationPreview;
    indexes: {
      'by-updated': number;
    };
  };
  messages: {
    key: string;
    value: IMessage;
    indexes: {
      'by-conversation': string;
      'by-created': number;
    };
  };
  attachments: {
    key: string;
    value: PendingAttachment;
  };
}

@Injectable({ providedIn: 'root' })
export class DatabaseService {
  private dbPromise: Promise<IDBPDatabase<OritaDB>> | null = null;
  private platformId = inject(PLATFORM_ID);

  constructor() {
    if (isPlatformBrowser(this.platformId)) {
      this.dbPromise = openDB<OritaDB>('orita-db', 1, {
        upgrade(db) {
          if (!db.objectStoreNames.contains('outgoing_messages')) {
            const outStore = db.createObjectStore('outgoing_messages', { keyPath: 'id' });
            outStore.createIndex('by-conversation', 'conversationId');
            outStore.createIndex('by-status', 'status');
            outStore.createIndex('by-created', 'createdAt');
          }
          if (!db.objectStoreNames.contains('conversations')) {
            const convStore = db.createObjectStore('conversations', { keyPath: 'id' });
            convStore.createIndex('by-updated', 'lastActivityAt'); // IConversationPreview uses lastActivityAt
          }
          if (!db.objectStoreNames.contains('messages')) {
            const msgStore = db.createObjectStore('messages', { keyPath: 'id' });
            msgStore.createIndex('by-conversation', 'conversationId');
            msgStore.createIndex('by-created', 'createdAt');
          }
          if (!db.objectStoreNames.contains('attachments')) {
            db.createObjectStore('attachments', { keyPath: 'id' });
          }
        },
      });
    }
  }

  // --- Outgoing Messages ---

  async saveQueuedMessage(message: QueuedMessage): Promise<void> {
    if (!this.dbPromise) return;
    const db = await this.dbPromise;
    await db.put('outgoing_messages', message);
  }

  async getQueuedMessages(): Promise<QueuedMessage[]> {
    if (!this.dbPromise) return [];
    const db = await this.dbPromise;
    return db.getAll('outgoing_messages');
  }

  async deleteQueuedMessage(id: string): Promise<void> {
    if (!this.dbPromise) return;
    const db = await this.dbPromise;
    await db.delete('outgoing_messages', id);
  }

  // --- Conversations ---

  async saveConversationPreview(preview: IConversationPreview): Promise<void> {
    if (!this.dbPromise) return;
    const db = await this.dbPromise;
    await db.put('conversations', preview);
  }

  async saveConversationPreviews(previews: IConversationPreview[]): Promise<void> {
    if (!this.dbPromise) return;
    const db = await this.dbPromise;
    const tx = db.transaction('conversations', 'readwrite');
    await Promise.all([
      ...previews.map(p => tx.store.put(p)),
      tx.done
    ]);
  }

  async getConversationPreviews(): Promise<IConversationPreview[]> {
    if (!this.dbPromise) return [];
    const db = await this.dbPromise;
    return db.getAllFromIndex('conversations', 'by-updated'); // Get them sorted if possible
  }

  // --- Messages ---

  async saveMessage(message: IMessage): Promise<void> {
    if (!this.dbPromise) return;
    const db = await this.dbPromise;
    await db.put('messages', message);
  }

  async saveMessages(messages: IMessage[]): Promise<void> {
    if (!this.dbPromise) return;
    const db = await this.dbPromise;
    const tx = db.transaction('messages', 'readwrite');
    await Promise.all([
      ...messages.map(m => tx.store.put(m)),
      tx.done
    ]);
  }

  async getMessagesForConversation(conversationId: string): Promise<IMessage[]> {
    if (!this.dbPromise) return [];
    const db = await this.dbPromise;
    return db.getAllFromIndex('messages', 'by-conversation', conversationId);
  }

  // --- Attachments ---

  async saveAttachment(attachment: PendingAttachment): Promise<void> {
    if (!this.dbPromise) return;
    const db = await this.dbPromise;
    await db.put('attachments', attachment);
  }

  async getAttachment(id: string): Promise<PendingAttachment | undefined> {
    if (!this.dbPromise) return undefined;
    const db = await this.dbPromise;
    return db.get('attachments', id);
  }

  async deleteAttachment(id: string): Promise<void> {
    if (!this.dbPromise) return;
    const db = await this.dbPromise;
    await db.delete('attachments', id);
  }
}

