import { Service, computed, signal, Signal } from '@angular/core';
import { DISTANCE_THRESHOLD, DrawerPosition, VELOCITY_THRESHOLD } from './drawer.model';

interface PointerState {
  startX: number;
  startY: number;
  startTime: number;
  currentDelta: number;
  active: boolean;
}

@Service()
export class DrawerDragService {
  private pointer: PointerState = {
    startX: 0,
    startY: 0,
    startTime: 0,
    currentDelta: 0,
    active: false,
  };

  readonly dragDelta = signal(0);
  readonly isDragging = signal(false);

  private position!: Signal<DrawerPosition>;
  private isCenter!: Signal<boolean>;
  private isVertical!: Signal<boolean>;
  private dismissible!: Signal<boolean>;
  private drawerSizePx!: () => number;
  private requestClose!: () => void;

  init(config: {
    position: Signal<DrawerPosition>;
    isCenter: Signal<boolean>;
    isVertical: Signal<boolean>;
    dismissible: Signal<boolean>;
    drawerSizePx: () => number;
    requestClose: () => void;
  }): void {
    this.position = config.position;
    this.isCenter = config.isCenter;
    this.isVertical = config.isVertical;
    this.dismissible = config.dismissible;
    this.drawerSizePx = config.drawerSizePx;
    this.requestClose = config.requestClose;
  }

  readonly dragTransform = computed(() => {
    const delta = this.dragDelta();
    if (delta === 0) return '';
    const pos = this.position();
    switch (pos) {
      case 'left':
        return `translateX(${Math.min(delta, 0)}px)`;
      case 'right':
        return `translateX(${Math.max(delta, 0)}px)`;
      case 'top':
        return `translateY(${Math.min(delta, 0)}px)`;
      case 'bottom':
        return `translateY(${Math.max(delta, 0)}px)`;
      default:
        return '';
    }
  });

  reset(): void {
    this.dragDelta.set(0);
    this.isDragging.set(false);
    this.pointer.active = false;
  }

  onPointerDown(event: PointerEvent): void {
    if (this.isCenter() || !this.dismissible()) return;
    const handle = event.currentTarget as HTMLElement;
    handle.setPointerCapture(event.pointerId);
    this.pointer = {
      startX: event.clientX,
      startY: event.clientY,
      startTime: event.timeStamp,
      currentDelta: 0,
      active: true,
    };
    this.isDragging.set(true);
  }

  onPointerMove(event: PointerEvent): void {
    if (!this.pointer.active) return;
    const rawDelta = this.isVertical()
      ? event.clientY - this.pointer.startY
      : event.clientX - this.pointer.startX;
    const resistedDelta = this.resistDelta(rawDelta);
    this.pointer.currentDelta = resistedDelta;
    this.dragDelta.set(resistedDelta);
  }

  onPointerUp(event: PointerEvent): void {
    if (!this.pointer.active) return;
    const delta = Math.abs(this.pointer.currentDelta);
    const elapsed = event.timeStamp - this.pointer.startTime;
    const velocity = elapsed > 0 ? delta / elapsed : 0;
    const size = this.drawerSizePx();

    const pastDistance = size > 0 && delta / size > DISTANCE_THRESHOLD;
    const pastVelocity = velocity > VELOCITY_THRESHOLD;

    if (pastDistance || pastVelocity) {
      this.requestClose();
    }
    this.reset();
  }

  onPointerCancel(): void {
    this.reset();
  }

  private resistDelta(raw: number): number {
    const pos = this.position();
    const isClosingDirection =
      (pos === 'left' && raw < 0) ||
      (pos === 'right' && raw > 0) ||
      (pos === 'top' && raw < 0) ||
      (pos === 'bottom' && raw > 0);

    if (isClosingDirection) return raw;
    return raw * 0.15;
  }
}

import { Service, inject } from '@angular/core';
import { DOCUMENT } from '@angular/common';

@Service()
export class DrawerFocusService {
  private document = inject(DOCUMENT);
  private lastFocusedElement: HTMLElement | null = null;

  remember(): void {
    const active = this.document.activeElement;
    this.lastFocusedElement = active instanceof HTMLElement ? active : null;
  }

  restore(): void {
    this.lastFocusedElement?.focus();
    this.lastFocusedElement = null;
  }

  trapFocus(panel: HTMLElement, event: KeyboardEvent): void {
    if (event.key !== 'Tab') return;

    const focusableSelectors = [
      'a[href]',
      'button:not([disabled])',
      'textarea:not([disabled])',
      'input:not([disabled])',
      'select:not([disabled])',
      '[tabindex]:not([tabindex="-1"])'
    ].join(', ');

    const focusableElements = Array.from(
      panel.querySelectorAll<HTMLElement>(focusableSelectors)
    ).filter(el => {
      // Exclude elements that are visually hidden but still in DOM
      return el.offsetWidth > 0 || el.offsetHeight > 0 || el.getClientRects().length > 0;
    });

    if (focusableElements.length === 0) {
      event.preventDefault();
      return;
    }

    const first = focusableElements[0];
    const last = focusableElements[focusableElements.length - 1];

    if (event.shiftKey) {
      if (this.document.activeElement === first || this.document.activeElement === panel) {
        last.focus();
        event.preventDefault();
      }
    } else {
      if (this.document.activeElement === last) {
        first.focus();
        event.preventDefault();
      }
    }
  }
}

import { Service, inject } from '@angular/core';
import { DOCUMENT } from '@angular/common';

@Service()
export class DrawerScrollService {
  private document = inject(DOCUMENT);
  private count = 0;

  lock(): void {
    if (this.count === 0) {
      this.document.body.style.overflow = 'hidden';
    }
    this.count++;
  }

  unlock(): void {
    if (this.count <= 0) return;
    this.count--;
    if (this.count === 0) {
      this.document.body.style.overflow = '';
    }
  }
}

import { Service, computed, inject, signal } from '@angular/core';
import { firstValueFrom, catchError, of } from 'rxjs';
import { HttpClient } from '@angular/common/http';
import { ExplorationStorage, ActiveLocation } from './exploration-storage';
import { LocationService } from './location.service';
import { CookieService } from './cookie';
import { environment } from '../../../environments/environment';

@Service()
export class ExplorationService {
  #storage = inject(ExplorationStorage);
  #locationService = inject(LocationService);
  #http = inject(HttpClient);
  #cookie = inject(CookieService);

  readonly activeLocation = signal<ActiveLocation | null>(this.#storage.get());
  readonly hasLocation = computed(() => !!this.activeLocation());
  readonly isLocationPickerOpen = signal<boolean>(false);

  constructor() {
    this.hydrateFromBackendIfNeeded();
  }

  private get isAuthenticated(): boolean {
    return !!this.#cookie.get('auth_token');
  }

  private async hydrateFromBackendIfNeeded() {
    if (this.isAuthenticated && !this.activeLocation()) {
      try {
        const profile = await firstValueFrom(
          this.#http.get<any>(`${environment.apiUrl}/users/me`)
        );
        if (profile?.activeExplorationLat && profile?.activeExplorationLng) {
          const context: ActiveLocation = {
            id: 'backend_sync',
            name: profile.activeExplorationName || 'Saved Location',
            city: null,
            state: null,
            country: null,
            lat: profile.activeExplorationLat,
            lng: profile.activeExplorationLng,
          };
          this.#storage.set(context);
          this.activeLocation.set(context);
        }
      } catch (err) {
        // Ignored
      }
    }
  }

  private async syncToBackend(context: ActiveLocation) {
    if (this.isAuthenticated) {
      try {
        await firstValueFrom(
          this.#http.patch(`${environment.apiUrl}/users/me/exploration-context`, {
            latitude: context.lat,
            longitude: context.lng,
            name: context.name,
          }).pipe(catchError(() => of(null)))
        );
      } catch (err) {
        // Ignored
      }
    }
  }

  setLocation(context: ActiveLocation): void {
    this.#storage.set(context);
    this.activeLocation.set(context);
    this.syncToBackend(context);
  }

  clearLocation(): void {
    this.#storage.clear();
    this.activeLocation.set(null);
  }

  async setFromGps(): Promise<ActiveLocation> {
    return new Promise((resolve, reject) => {
      if (!navigator.geolocation) {
        reject(new Error('Geolocation is not supported by your browser'));
        return;
      }

      navigator.geolocation.getCurrentPosition(
        async (position) => {
          try {
            const { latitude, longitude } = position.coords;
            const res = await firstValueFrom(this.#locationService.reverseGeocode(latitude, longitude));

            const newContext: ActiveLocation = {
              id: res?.id || `gps_${latitude}_${longitude}`,
              name: res?.name || 'Current Location',
              city: res?.formattedAddress || null, // simplified since we just have formattedAddress
              state: null,
              country: null,
              lat: latitude,
              lng: longitude,
            };

            this.setLocation(newContext);
            resolve(newContext);
          } catch (error) {
            reject(error);
          }
        },
        (error) => {
          reject(error);
        }
      );
    });
  }
}

import { Service, inject, Injectable } from '@angular/core';
import { CookieService } from './cookie';
import { environment } from '../../../environments/environment';

export interface ActiveLocation {
  id: string;
  name: string;
  city: string | null;
  state: string | null;
  country: string | null;
  lat: number;
  lng: number;
}

@Injectable()
export abstract class ExplorationStorage {
  abstract get(): ActiveLocation | null;
  abstract set(context: ActiveLocation): void;
  abstract clear(): void;
}

@Service()
export class CookieExplorationStorage extends ExplorationStorage {
  private readonly COOKIE_KEY = 'orita.exploration';
  #cookieService = inject(CookieService);

  get(): ActiveLocation | null {
    const raw = this.#cookieService.get(this.COOKIE_KEY);
    if (!raw) return null;
    try {
      return JSON.parse(raw) as ActiveLocation;
    } catch (e) {
      return null;
    }
  }

  set(context: ActiveLocation): void {
    // 1 year expiry
    const expires = new Date();
    expires.setFullYear(expires.getFullYear() + 1);

    this.#cookieService.set(this.COOKIE_KEY, JSON.stringify(context), {
      expires,
      path: '/',
      sameSite: 'Lax',
      secure: environment.production
    });
  }

  clear(): void {
    this.#cookieService.delete(this.COOKIE_KEY, { path: '/', sameSite: 'Lax' });
  }
}

