@Service()
export class SearchService {
  #apiUrl = `${environment.apiUrl}/search`;

  private buildUrl(base: string, params: SearchFilters | null): string | undefined {
    if (!params) return undefined;

    const urlParams = new URLSearchParams();

    Object.entries(params).forEach(([key, value]) => {
      if (value !== undefined && value !== null) {
        if (Array.isArray(value)) {
          value.forEach(v => {
            urlParams.append(key, v);
          });
        } else {
          urlParams.append(key, String(value));
        }
      }
    });

    const qs = urlParams.toString();
    return `${base}${qs ? `?${qs}` : ''}`;
  }

  getListingsResource(paramsSignal: Signal<SearchFilters | null>) {
    return httpResource<IPaginated<IListingSummary>>(() => 
      this.buildUrl(`${this.#apiUrl}/listings`, paramsSignal())
    );
  }

  getBusinessesResource(paramsSignal: Signal<SearchFilters | null>) {
    return httpResource<IPaginated<IBusinessSummary>>(() => 
      this.buildUrl(`${this.#apiUrl}/businesses`, paramsSignal())
    );
  }

  getUsersResource(paramsSignal: Signal<SearchFilters | null>) {
    return httpResource<IPaginated<IProfile>>(() => 
      this.buildUrl(`${this.#apiUrl}/users`, paramsSignal())
    );
  }

  getToursResource(paramsSignal: Signal<SearchFilters | null>) {
    return httpResource<IPaginated<any>>(() => 
      this.buildUrl(`${this.#apiUrl}/tours`, paramsSignal())
    );
  }
}

import { Service, inject } from '@angular/core';
import { Title, Meta } from '@angular/platform-browser';
import { DOCUMENT } from '@angular/common';

export interface SeoConfig {
  title?: string;
  description?: string;
  image?: string;
  url?: string;
  type?: 'website' | 'article' | 'profile' | 'product';
  jsonLd?: Record<string, any>;
}

@Service()
export class SeoService {
  #title = inject(Title);
  #meta = inject(Meta);
  #document = inject(DOCUMENT);

  private readonly defaultTitle = 'Orita';
  private readonly defaultDesc = 'Local discovery platform connecting people with businesses, services, and opportunities around them.';
  private readonly defaultImage = 'https://inquisitive-ernestine-odysseon-ae88add1.koyeb.app/logo.png';

  generateTags(config: SeoConfig) {
    const title = config.title ? `${config.title} | Orita` : this.defaultTitle;
    this.#title.setTitle(title);

    const description = config.description || this.defaultDesc;
    this.#meta.updateTag({ name: 'description', content: description });

    // Open Graph
    this.#meta.updateTag({ property: 'og:title', content: title });
    this.#meta.updateTag({ property: 'og:description', content: description });
    this.#meta.updateTag({ property: 'og:type', content: config.type || 'website' });
    this.#meta.updateTag({ property: 'og:image', content: config.image || this.defaultImage });

    if (config.url) {
      this.#meta.updateTag({ property: 'og:url', content: config.url });
    }

    // Twitter Card
    this.#meta.updateTag({ name: 'twitter:card', content: 'summary_large_image' });
    this.#meta.updateTag({ name: 'twitter:title', content: title });
    this.#meta.updateTag({ name: 'twitter:description', content: description });
    this.#meta.updateTag({ name: 'twitter:image', content: config.image || this.defaultImage });

    // JSON-LD Structured Data
    if (config.jsonLd) {
      this.insertJsonLd(config.jsonLd);
    } else {
      this.removeJsonLd();
    }
  }

  private insertJsonLd(schema: Record<string, any>) {
    this.removeJsonLd();

    const script = this.#document.createElement('script');
    script.type = 'application/ld+json';
    script.id = 'seo-json-ld';
    script.textContent = JSON.stringify({
      '@context': 'https://schema.org',
      ...schema
    });
    this.#document.head.appendChild(script);
  }

  private removeJsonLd() {
    const existing = this.#document.getElementById('seo-json-ld');
    if (existing) {
      existing.remove();
    }
  }
}

import { Service, inject, signal } from '@angular/core';
import { ShareIntent, ShareTarget } from '../../types/share.types.js';
import { LinkBuilderService } from './link-builder.service.js';
import { NativeShareService } from './native-share.service.js';
import { ClipboardService } from './clipboard.service.js';
import { MessagingApiService } from '../../services/messaging-api.service';
import { firstValueFrom } from 'rxjs';
import { Router } from '@angular/router';
import { mapIntentToEmbed } from './share-embed.mapper.js';

export type ShareStatus = 'idle' | 'opening' | 'sending' | 'failed' | 'complete';

import { MessagingRepository } from '../../services/messaging-repository.service';

@Service()
export class ShareFacade {
  #linkBuilder = inject(LinkBuilderService);
  #nativeShare = inject(NativeShareService);
  #clipboard = inject(ClipboardService);
  #messagingApi = inject(MessagingApiService);
  #messagingRepo = inject(MessagingRepository);
  #router = inject(Router);

  status = signal<ShareStatus>('idle');
  recentChats = signal<any[]>([]); // Using any for now to avoid deep type imports if not available

  constructor() {
    this.loadRecentChats();
  }

  async loadRecentChats() {
    try {
      const chats = await firstValueFrom(this.#messagingApi.getConversations());
      this.recentChats.set(chats);
    } catch (e) {
      console.error('Failed to load recent chats', e);
    }
  }

  async copyLink(intent: ShareIntent): Promise<void> {
    try {
      this.status.set('sending');
      const url = this.#linkBuilder.buildLink(intent);
      await this.#clipboard.copy(url);
      this.status.set('complete');
    } catch (e) {
      this.status.set('failed');
      throw e;
    } finally {
      setTimeout(() => { if (this.status() === 'complete' || this.status() === 'failed') this.status.set('idle'); }, 2000);
    }
  }

  async nativeShare(intent: ShareIntent): Promise<void> {
    try {
      this.status.set('sending');
      const url = this.#linkBuilder.buildLink(intent);
      await this.#nativeShare.share(url);
      this.status.set('complete');
    } catch (e) {
      this.status.set('failed');
      throw e;
    } finally {
      setTimeout(() => { if (this.status() === 'complete' || this.status() === 'failed') this.status.set('idle'); }, 2000);
    }
  }

  async share(intent: ShareIntent, target: ShareTarget): Promise<void> {
    this.status.set('opening');
    try {
      let conversationId = '';

      if (target.kind === 'conversation') {
        conversationId = target.conversationId;
      } else {
        const conversation = await firstValueFrom(
          this.#messagingApi.openConversation('USER', target.userId)
        );
        conversationId = conversation.id;
      }

      this.status.set('sending');

      const embed = mapIntentToEmbed(intent);

      await this.#messagingRepo.sendMessage(conversationId, {
        embeds: [embed],
      });

      this.status.set('complete');

      await this.#router.navigate(['/messages', conversationId]);

    } catch (error) {
      this.status.set('failed');
      throw error;
    } finally {
      setTimeout(() => { if (this.status() === 'complete' || this.status() === 'failed') this.status.set('idle'); }, 2000);
    }
  }
}

import { Service, inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { ToastService } from './toast';

import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../environments/environment';

export interface ShareData {
  title?: string;
  text?: string;
  url?: string;
}

export interface SuggestedShareRecipientDto {
  userId: string;
  username: string;
  displayName?: string;
  avatarUrl?: string;
}

export interface RecentShareableDto {
  type: 'BUSINESS' | 'LISTING' | 'TOUR';
  targetId: string;
  title: string;
  imageUrl?: string;
  lastInteractedAt: string;
}

export interface ShareableSearchResult {
  type: 'BUSINESS' | 'LISTING' | 'TOUR';
  targetId: string;
  title: string;
  subtitle?: string;
  imageUrl?: string;
}

export interface InternalShareDto {
  embedType: 'BUSINESS' | 'LISTING' | 'TOUR' | 'LOCATION';
  targetId: string;
  recipientIds: string[];
  content?: string;
}

export interface ShareResultDto {
  recipientId: string;
  conversationId: string;
  messageId: string;
}

@Service()
export class ShareService {
  #platformId = inject(PLATFORM_ID);
  #toast = inject(ToastService);
  #http = inject(HttpClient);

  readonly isSupported = isPlatformBrowser(this.#platformId) && !!navigator.share;

  async share(data: ShareData): Promise<void> {
    if (!isPlatformBrowser(this.#platformId)) return;

    if (this.isSupported) {
      try {
        await navigator.share(data);
      } catch (err) {
        // AbortError is perfectly normal (user canceled share sheet). We only care about other errors.
        if (err instanceof DOMException && err.name === 'AbortError') return;
        this.#fallback(data);
      }
    } else {
      this.#fallback(data);
    }
  }

  async #fallback(data: ShareData): Promise<void> {
    const textToCopy = data.url || data.text || '';
    if (!textToCopy) return;

    try {
      await navigator.clipboard.writeText(textToCopy);
      this.#toast.success('Link copied', 'The link has been copied to your clipboard.');
    } catch (err) {
      this.#toast.error('Copy failed', 'Unable to copy to clipboard.');
    }
  }

  async getSuggestedRecipients(): Promise<SuggestedShareRecipientDto[]> {
    return firstValueFrom(this.#http.get<SuggestedShareRecipientDto[]>(`${environment.apiUrl}/sharing/suggested-recipients`));
  }

  async getRecentShares(): Promise<RecentShareableDto[]> {
    return firstValueFrom(this.#http.get<RecentShareableDto[]>(`${environment.apiUrl}/sharing/recent`));
  }

  async searchShareables(query: string): Promise<ShareableSearchResult[]> {
    return firstValueFrom(this.#http.get<ShareableSearchResult[]>(`${environment.apiUrl}/search/shareables`, { params: { q: query } }));
  }

  async shareInternal(dto: InternalShareDto): Promise<ShareResultDto[]> {
    return firstValueFrom(this.#http.post<ShareResultDto[]>(`${environment.apiUrl}/share/internal`, dto));
  }
}

import { Service, inject, signal, PLATFORM_ID, effect } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { CookieService } from './cookie';

export type ThemePreference = 'system' | 'light' | 'dark';

const THEME_KEY = 'theme';

@Service()
export class ThemeService {
  #cookie = inject(CookieService);
  #platformId = inject(PLATFORM_ID);

  readonly preference = signal<ThemePreference>(
    (this.#cookie.get(THEME_KEY) as ThemePreference) ?? 'system',
  );

  #mediaQuery = isPlatformBrowser(this.#platformId) ? window.matchMedia('(prefers-color-scheme: dark)') : null;

  constructor() {
    if (this.#mediaQuery) {
      this.#mediaQuery.addEventListener('change', () => {
        if (this.preference() === 'system') {
          this.#apply('system');
        }
      });
    }
    effect(() => {
      this.#apply(this.preference());
    });
  }

  set(preference: ThemePreference): void {
    this.preference.set(preference);
    this.#cookie.set(THEME_KEY, preference, {
      expires: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000),
      sameSite: 'Strict',
      secure: false,
    });
  }

  #apply(preference: ThemePreference): void {
    if (!isPlatformBrowser(this.#platformId)) return;
    const html = document.documentElement;

    let resolvedTheme = preference;
    if (preference === 'system') {
      resolvedTheme = this.#mediaQuery?.matches ? 'dark' : 'light';
    }

    html.setAttribute('data-theme', resolvedTheme);
  }
}

import { Service, signal } from '@angular/core';

export type ToastIntent = 'success' | 'error' | 'info' | 'warning';

export interface Toast {
  id: number;
  intent: ToastIntent;
  title: string;
  message?: string;
}

let nextId = 0;

@Service()
export class ToastService {
  readonly toasts = signal<Toast[]>([]);

  success(title: string, message?: string): void {
    this.#push('success', title, message);
  }

  error(title: string, message?: string): void {
    this.#push('error', title, message);
  }

  info(title: string, message?: string): void {
    this.#push('info', title, message);
  }

  warning(title: string, message?: string): void {
    this.#push('warning', title, message);
  }

  dismiss(id: number): void {
    this.toasts.update((list) => list.filter((t) => t.id !== id));
  }

  #push(intent: ToastIntent, title: string, message?: string): void {
    const id = nextId++;
    this.toasts.update((list) => [...list, { id, intent, title, message }]);
    setTimeout(() => this.dismiss(id), 4000);
  }
}

