.drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: var(--z-modal);
  background: oklch(18% 0.02 280 / 0.16);
  opacity: 0;
  transition: opacity var(--duration-normal) var(--ease-standard);
  cursor: pointer;
}

.drawer-backdrop--open {
  opacity: 1;
}

.drawer-panel {
  position: fixed;
  z-index: var(--z-modal);
  background: var(--surface-card);
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  transition:
    transform var(--duration-slow) var(--ease-decelerate),
    opacity var(--duration-slow) var(--ease-standard);
  touch-action: none;
  will-change: transform;
  outline: none;
}

.drawer-panel--dragging {
  transition: none;
}

/* Positions — closed state */
.drawer-panel--left {
  top: 0;
  left: 0;
  bottom: 0;
  transform: translateX(-100%);
  border-radius: 0 var(--radius-lg) var(--radius-lg) 0;
}

.drawer-panel--right {
  top: 0;
  right: 0;
  bottom: 0;
  transform: translateX(100%);
  border-radius: var(--radius-lg) 0 0 var(--radius-lg);
}

.drawer-panel--top {
  top: 0;
  left: 0;
  right: 0;
  transform: translateY(-100%);
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
}

.drawer-panel--bottom {
  bottom: 0;
  left: 0;
  right: 0;
  transform: translateY(100%);
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
}

.drawer-panel--center {
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0.96);
  opacity: 0;
}

/* Open state */
.drawer-panel--open.drawer-panel--left,
.drawer-panel--open.drawer-panel--right {
  transform: translateX(0);
}

.drawer-panel--open.drawer-panel--top,
.drawer-panel--open.drawer-panel--bottom {
  transform: translateY(0);
}

.drawer-panel--open.drawer-panel--center {
  transform: translate(-50%, -50%) scale(1);
  opacity: 1;
}

/* Drag handle — fixed at top, never scrolls */
.drawer-drag-handle {
  flex-shrink: 0;
  width: var(--size-48);
  height: var(--size-4);
  background: var(--border-default);
  border-radius: var(--radius-pill);
  margin: var(--space-xs) auto 0 auto;
  cursor: grab;
  touch-action: none;
}

.drawer-drag-handle:active {
  cursor: grabbing;
}

.drawer-drag-handle--disabled {
  cursor: default;
}

/* Header */
.drawer-header {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  min-height: var(--size-48);
  padding: 0 var(--space-sm) var(--size-12);
  border-bottom: var(--size-1) solid var(--border-subtle);
  flex-shrink: 0;
}

.drawer-title {
  grid-column: 2;
  text-align: center;
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  color: var(--text-primary);
}

.drawer-close {
  grid-column: 3;
  justify-self: end;
  width: var(--size-32);
  height: var(--size-32);
  border: none;
  border-radius: var(--radius-pill);
