.edit-biz-page {
  display: flex;
  flex-direction: column;
  gap: var(--size-20);
  max-width: 640px;
  margin: 0 auto;
  padding: var(--size-16) var(--size-16) var(--size-48);
}

.edit-biz-skeleton {
  display: flex;
  flex-direction: column;
  gap: var(--size-16);
}

.edit-biz-form {
  display: flex;
  flex-direction: column;
  gap: var(--size-20);
}

.edit-biz-panel-body {
  padding: var(--size-20);
  display: flex;
  flex-direction: column;
  gap: var(--size-16);
}

/* TYPE SELECTOR */
.biz-type-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--size-8);
  margin-top: var(--size-4);
}

.biz-type-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--size-4);
  padding: var(--size-12) var(--size-8);
  background: var(--surface-card);
  border: var(--size-1-5) solid var(--border-subtle);
  border-radius: var(--radius-md);
  cursor: pointer;
  text-align: center;
  font-family: var(--font-sans);
  transition:
    border-color var(--transition-fast),
    background var(--transition-fast);

  &:hover {
    border-color: var(--border-default);
    background: var(--surface-container);
  }
}

.biz-type-card--selected {
  border-color: var(--clr-primary);
  background: var(--clr-primary-container);

  .biz-type-card__label {
    color: var(--clr-primary);
  }
}

.biz-type-card__label {
  font-size: var(--font-size-md);
  font-weight: var(--font-weight-medium);
  color: var(--text-primary);
}

.biz-type-card__desc {
  font-size: var(--font-size-xs);
  color: var(--text-muted);
  line-height: var(--line-height-normal);
}

/* TOGGLE SWITCH */
.field-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--size-16);
}

.field-toggle-text {
  display: flex;
  flex-direction: column;
  gap: var(--size-2);
}

.field-toggle-label {
  font-size: var(--font-size-md);
  font-weight: var(--font-weight-medium);
  color: var(--text-primary);
}

.field-toggle-hint {
  font-size: var(--font-size-sm);
  color: var(--text-muted);
}

.toggle-switch {
  position: relative;
  display: inline-block;
  width: 44px;
  height: 24px;
  flex-shrink: 0;

  input {
    opacity: 0;
    width: 0;
    height: 0;
  }
}

.toggle-slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--border-default);
  transition: var(--transition-fast);
  border-radius: var(--radius-pill);

  &::before {
    position: absolute;
    content: "";
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: var(--transition-fast);
    border-radius: var(--radius-pill);
    box-shadow: var(--shadow-sm);
  }
}

input:checked + .toggle-slider {
  background-color: var(--clr-primary);
}

input:checked + .toggle-slider::before {
  transform: translateX(20px);
}

/* ACTIONS */
.form-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: var(--size-8);
}

.spinner {
  width: var(--size-16);
  height: var(--size-16);
  animation: spin 0.8s linear infinite;
}

.edit-biz-error {
  display: flex;
  justify-content: center;
  padding: var(--size-48) var(--size-24);
  color: var(--clr-error);
  text-align: center;
  font-size: var(--font-size-md);
}

/* SECONDARY CATEGORIES */
.secondary-categories-grid {
  display: flex;
  flex-wrap: wrap;
  gap: var(--size-8);
}

.category-chip {
  padding: var(--size-6) var(--size-12);
  background: var(--surface-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--transition-fast);
}

