    <div style="display: flex; align-items: flex-start; justify-content: space-between; gap: var(--size-12);">
      <div>
        <h1 class="listing-main__title">{{ item.title }}</h1>
        <span class="listing-main__price">{{ priceLabel() }}</span>
      </div>
      <div style="display: flex; gap: var(--size-8);">
        <button class="btn btn--icon btn--outline" (click)="showShareModal.set(true)" aria-label="Send">
          <svg lucideSend aria-hidden="true"></svg>
        </button>
        <app-share-button [title]="item.title" [text]="item.description || ''" />
      </div>
    </div>

    @if (avgRating(); as rating) {
    <div class="listing-rating">
      <div class="listing-rating__stars">
        @for (filled of starArray(Math.round(+rating)); track $index) {
        <svg lucideStar [class.star--filled]="filled" aria-hidden="true"></svg>
        }
      </div>
      <span class="listing-rating__value">{{ rating }}</span>
      <span class="listing-rating__count">({{ item.reviews!.length }} reviews)</span>
    </div>
    }
  </div>

  <!-- Description -->
  @if (item.description) {
  <p class="listing-description">{{ item.description }}</p>
  }

  <!-- Category Attributes -->
  @if (attributesResource.hasValue() && attributesResource.value()!.length > 0) {
  <app-listing-attributes [attributes]="attributesResource.value()!" />
  }

  <!-- Business card -->
  @if (business.hasValue()) { @let biz = business.value()!;
  <app-listing-business-card [biz]="biz" [listingId]="item.id" />
  }

  <!-- Reviews -->
  @if (item.reviews && item.reviews.length > 0) {
  <app-listing-reviews [reviews]="item.reviews" />
  }
</div>

<app-share-modal
  [isOpen]="showShareModal()"
  (close)="showShareModal.set(false)"
  embedType="LISTING"
  [targetId]="item.id"
  [title]="item.title"
  [subtitle]="business.value()?.name"
  [imageUrl]="item.coverUrl"
/>
}

