  top: 50%;
  right: var(--space-sm);
  transform: translateY(-50%);
}

:host-context(.nav-list-side:not(.expanded)) .nav-item-badge-wrapper {
  top: var(--size-4);
  right: var(--size-4);
  transform: none;
}

/* Active Styles */

:host(.active) .nav-item-btn {
  color: var(--clr-primary);
}

:host(.active) .nav-item-icon-wrapper {
  color: var(--clr-primary);
}

:host(.active) .nav-item-btn:hover:not(:disabled) {
  background: var(--clr-primary-container);
}

.nav-item-label-wrapper::after {
  content: '';
  position: absolute;
  background-color: var(--clr-primary);
  transition: transform var(--transition-fast);
  border-radius: var(--radius-pill);
}

/* Vertical underline */
:host(.nav-item-vertical) .nav-item-label-wrapper::after {
  bottom: calc(-1 * var(--space-2xs));
  left: 10%;
  width: 80%;
  height: var(--size-2);
  transform: scaleX(0);
  transform-origin: center;
}

/* Horizontal underline (left indicator) */
:host(.nav-item-horizontal) .nav-item-label-wrapper::after {
  left: calc(-1 * var(--space-md));
  top: 20%;
  width: var(--size-4);
  height: 60%;
  transform: scaleY(0);
  transform-origin: center;
}

/* Activate underline ONLY if there is NO icon projected */
:host(.nav-item-vertical.active)
  .nav-item-btn:not(:has(.nav-item-icon-wrapper > *))
  .nav-item-label-wrapper::after {
  transform: scaleX(1);
}

:host(.nav-item-horizontal.active)
  .nav-item-btn:not(:has(.nav-item-icon-wrapper > *))
  .nav-item-label-wrapper::after {
  transform: scaleY(1);
}

/* Focus */
.nav-item-btn:focus-visible {
  outline: 2px solid var(--clr-primary);
  outline-offset: 2px;
}

