.search-input::placeholder {
  color: var(--text-muted);
}

.search-input:focus {
  background: var(--surface-card);
  border-color: var(--clr-primary);
}

/* -- Composer ----------------------------------------------------- */
.composer-row {
  display: flex;
  align-items: center;
  gap: var(--size-12);
  padding: var(--space-xs) var(--space-sm);
  border-top: var(--size-1) solid var(--border-subtle);
