  background: var(--surface-card);
}

.send-btn {
  display: flex;
  align-items: center;
  gap: var(--size-6);
  min-height: var(--size-40); /* was implicit ~32px via padding */
  background: var(--clr-primary);
  color: var(--clr-on-primary);
  border: none;
  border-radius: var(--radius-pill);
  padding: var(--size-8) var(--space-sm);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  flex-shrink: 0;
  transition:
    background var(--transition-fast),
    opacity var(--transition-fast);
}

.send-btn:hover:not(:disabled) {
  background: var(--clr-primary-dark);
}

.send-btn:disabled {
  background: var(--surface-container-high);
  color: var(--text-muted);
  cursor: not-allowed;
}

.send-badge {
  background: var(--clr-on-primary);
  color: var(--clr-primary);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-semibold);
  min-width: var(--size-16);
  height: var(--size-16);
  border-radius: var(--radius-pill);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 var(--size-4);
}

.send-icon {
  width: var(--size-16);
  height: var(--size-16);
}

/* -- Small phones: tighten density ------------------------------- */
@media (max-width: 380px) {
  .target-image,
  .target-image-placeholder {
    width: var(--size-40);
    height: var(--size-40);
  }

  .selected-chip span {
    max-width: var(--size-64);
  }
}

/* -- Tablet / desktop: stop being a full-bleed sheet -------------- */
@media (min-width: 640px) {
  .share-modal-content {
    max-width: var(--size-480);
    max-height: 640px;
    margin-inline: auto;
    border-radius: var(--radius-xl) var(--radius-xl) 0 0;
  }
}

/* -- Reduced motion ------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  .close-btn,
  .search-input,
  .message-input,
  .send-btn {
    transition-duration: 1ms;
  }
}

